function renderNav(filter='') {
  const query = filter.trim().toLocaleLowerCase();
  nav.innerHTML = groups.map(([group,items]) => {
    const shown = items.filter(([id,zh,en,summary]) => [zh,en,summary].some(value => value.toLocaleLowerCase().includes(query)));
    return shown.length ? `<div class="nav-group"><div class="group-title">${esc(group)}</div>${shown.map(([id,zh,en]) => `<a class="nav-item ${location.hash === '#'+id ? 'active' : ''}" href="#${esc(id)}">${esc(zh)}<small>${esc(en)}</small></a>`).join('')}</div>` : '';
  }).join('') || '<div class="no-results">找不到符合的主題。請試試英文名稱或其他關鍵字。</div>';
}

function homePage() {
  const total = Object.keys(pages).length-1;
  return `<article class="doc"><div class="eyebrow">SECURITY POSTURE MANAGEMENT / 學習索引</div><h1>從自身資安態勢到改善追蹤</h1><p class="lead">這份繁體中文教學索引整理 ${total} 個 SPM 功能主題。先認識儀表板，再依左側的原介面選單查找專有名詞、功能與使用情境。</p><div class="callout"><strong>閱讀前先知道</strong><br>這是獨立製作的教學文件，非 BitSight 官方文件；不連接帳號，也不顯示即時資料。名稱與可用功能可能因版本、授權、權限及自訂設定而異。</div><h2>建議從這四步開始</h2><div class="journey">${[['dashboard','01','掌握整體狀況','查看評等、近期發現與資產變化。'],['findings-table','02','核對具體問題','檢查發現事項的證據、資產及時間。'],['infrastructure','03','確認資產歸屬','辨識對外可見的自身與第三方資產。'],['risk-remediation','04','安排改善追蹤','建立後續處理與驗證流程。']].map(([id,n,title,body]) => `<button class="journey-item" data-page="${id}"><b>${n}</b><span><strong>${title}</strong><small>${body}</small></span></button>`).join('')}</div><h2>依側欄範圍找主題</h2><div class="feature-grid">${groups.slice(1).map(([group,items]) => `<section class="feature-card"><strong>${esc(group)}</strong><p>${items.length} 個子頁，逐頁對照英文名稱與使用情境。</p><button class="text-link" data-page="${items[0][0]}">閱讀${esc(items[0][1])} →</button></section>`).join('')}</div><p class="note">頁面名稱依 2026-09-18 可見的 SPM 側欄整理。中文為教學用建議譯名。</p></article>`;
}

function dashboardPage() {
  return `<article class="doc"><button class="back-link" data-page="home">← 返回學習索引</button><div class="eyebrow">開始使用 / Dashboard</div><h1>儀表板</h1><p class="lead">My Company Dashboard 是自身組織資安態勢的摘要。先找出評等、重大發現或基礎設施的異常變化，再前往明細查證。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Dashboard</code>。頁首公司的選擇器會影響目前的分析對象，卡片也可能因帳號設定不同而異。</div><h2>頁首與共用控制</h2><div class="doc-table"><table><thead><tr><th>英文</th><th>中文與功能</th></tr></thead><tbody>${[['Security Posture Management','產品切換器，目前所在應用程式。'],['Search Company, Domain, or Page Name','搜尋公司、網域或頁面名稱。'],['Notifications','平台通知入口。'],['Settings','帳號與平台設定入口，內容依權限不同。'],['Assistant','產品內協助入口。'],['Add Cards','加入新的儀表板卡片。'],['Edit Dashboard','調整或移除儀表板卡片。'],['Select','設定個別卡片的公司或顯示範圍；選項依卡片不同。']].map(([a,b]) => `<tr><td><strong>${a}</strong></td><td>${b}</td></tr>`).join('')}</tbody></table></div><h2>資訊卡對照</h2><div class="guide-cards">${cards.map(([en,zh,body]) => `<section class="guide-card"><strong>${esc(zh)}</strong><small>${esc(en)}</small><p>${esc(body)}</p></section>`).join('')}</div><h2>建議操作流程</h2><ol><li>確認頂端選取的公司，避免把不同實體的資料混在一起。</li><li>檢查卡片所用的時間範圍（例如 30 Days 或 90 Days）。</li><li>優先查看新增高優先／重大發現、評等變化與基礎設施變化。</li><li>點入發現事項、弱點偵測或基礎設施，核對證據、首次與最近觀測時間、資產歸屬。</li><li>需要追蹤時進入議題追蹤、風險改善或警示設定。</li></ol><div class="example"><strong>使用情境：每日巡檢</strong><p>先看 Latest Updates 是否有與組織相關的安全事件，再檢查 New High Priority Findings 和 Infrastructure Changes。任何重要變化都要回到明細，而不只憑卡片數字作結論。</p></div><h2>容易誤判的地方</h2><ul><li>儀表板是摘要，不等於完整證據；空白卡片也可能受期間、權限或公司選擇影響。</li><li>資安評等、CVSS 與 DVE Score 衡量的面向不同，不應直接互相比大小。</li><li>不同卡片可獨立選擇範圍，跨卡片比較時先核對公司與時間條件。</li></ul><p class="note">依 2026-09-18 可見的 SPM 儀表板整理；不複製帳號內公司名稱、分數或訊息。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="findings-table"><strong>發現事項表格</strong><small>Findings Table · 追查具體問題。</small></button><button class="feature-card" data-page="infrastructure"><strong>基礎設施</strong><small>Infrastructure · 核對資產歸屬。</small></button></div></article>`;
}

function companyDetailsPage() {
  return `<article class="doc"><button class="back-link" data-page="home">← 返回學習索引</button><div class="eyebrow">組織 Organization / Company Details</div><h1>公司詳情</h1><p class="lead">Company Details 是 SPM 中單一公司的總覽頁。先確認目前選取的公司與評等期間，再從分數變化、弱點、感染訊號及資產範圍找出需要往下調查的問題。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Organization → Company Details</code>。頁首的 <code>Company Details for …</code> 指出目前公司；頁面上的數字與事件屬於該帳號的即時資料，本文件不複製。</div><h2>畫面怎麼看</h2><div class="guide-cards">${companySections.map(([en,zh,body]) => `<section class="guide-card"><strong>${esc(zh)}</strong><small>${esc(en)}</small><p>${esc(body)}</p></section>`).join('')}</div><h2>頁首與常用控制</h2>${docTable(['英文','建議中文','功能／判讀'],[['Reports','報表','從目前公司脈絡前往相關報表；產出前仍須確認範圍。'],['Actions','操作選單','目前公司可執行的動作入口；內容依帳號與權限不同。'],['Show Details','顯示詳情','展開公司背景資訊。'],['Select','選擇','調整評等變化等區塊的顯示條件。'],['View Ratings Tree','查看評等樹','前往組織節點及母子公司關係。'],['View Details','查看詳情','從摘要卡片進入對應的發現事項。'],['View Findings','查看發現事項','開啟影響評等的具體發現。'],['Remediation Plans','改善計畫','前往風險改善工作。']])}<h2>表格欄位與專有名詞</h2>${docTable(['原介面文字','建議中文','用途與注意'],companyTerms)}<h2>建議操作流程</h2><ol><li>確認頁首公司名稱、頂部公司選擇器與評等日期，避免在錯誤的組織範圍下判讀。</li><li>先看 <strong>Bitsight Security Rating</strong> 與 <strong>Security Ratings Changes</strong>；若分數改變，展開 <strong>Why?</strong> 核對是風險面向變化、具體事件，或演算法更新。</li><li>查看 <strong>Infections</strong> 和 <strong>Vulnerabilities</strong> 的觀測期間、嚴重度與受影響主機數，再點入明細。</li><li>對需要處理的問題，用 <strong>View Findings</strong> 確認資產與證據，必要時進入 <strong>Remediation Plans</strong> 追蹤改善。</li><li>若公司或 IP 範圍看起來不對，回到 <strong>Company Info</strong>、<strong>Network Footprint</strong> 與攻擊面頁核對歸屬。</li></ol><div class="example"><strong>使用情境：分數下降</strong><p>先固定公司與日期，閱讀評等變化清單的 Why?；若是某個 Risk Vector 下降，接著查看該面向與相應發現事項。若畫面標示 Ratings Algorithm Update，應先辨別方法變更與真實環境變化，不能直接把所有分數下降歸咎於新弱點。</p></div><div class="example"><strong>使用情境：向主管解釋風險</strong><p>用資安評等與趨勢說明整體態勢，但要列出關鍵發現、受影響資產及資料日期。Risk of Security Incidents 的倍數是比較風險訊號，不是「已發生事故」的證明；Self-Attested Compliance 則是組織自行聲明，不是 BitSight 審核結果。</p></div><h2>容易誤判的地方</h2><ul><li><strong>評等不等於事件：</strong>低評等或相對風險較高，不能直接推論已遭入侵。</li><li><strong>比較基準不同：</strong>產業中位數、投資組合平均與單一公司評等不能混用。</li><li><strong>受影響主機需查證：</strong>外部觀測可能受資產歸屬、資料延遲或可見範圍影響。</li><li><strong>估計改善分數不是保證：</strong>Remediation Strategy 的潛在影響以假設條件呈現，實際分數仍可能變動。</li><li><strong>自行聲明不是認證驗證：</strong>Self-Attested Compliance 不代表平台已獨立確認證書或法規符合性。</li></ul><p class="note">依 2026-09-18 可見的 SPM 公司詳情介面整理。中文為教學用建議譯名，非官方譯文；不同公司、授權與權限可能顯示不同卡片及資料。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="risk-vectors"><strong>風險面向</strong><small>Risk Vectors · 拆解評等構成。</small></button><button class="feature-card" data-page="findings-table"><strong>發現事項表格</strong><small>Findings Table · 核對具體證據。</small></button></div></article>`;
}

function riskVectorsPage() {
  return `<article class="doc"><button class="back-link" data-page="company-details">← 返回公司詳情</button><div class="eyebrow">組織 Organization / Risk Vectors</div><h1>風險面向</h1><p class="lead">Risk Vectors Overview 將資安評等拆成可調查的類別。與 CM 相同的概念與譯名沿用；SPM 頁面另外提供各類權重、個別等級與相對位置，幫助安排改善順序。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Organization → Risk Vectors</code>。頁首會顯示目前公司；先核對公司與日期，再解讀等級及權重。</div><h2>四大類別與子面向</h2>${vectorGroups.map(([en,zh,items]) => `<h3>${esc(zh)} <small>${esc(en)}</small></h3>${docTable(['英文','建議中文','看什麼'],items)}`).join('')}<h2>畫面控制與標記</h2>${docTable(['介面文字','建議中文','判讀方式'],[['Overview','總覽','先查看風險類別、主要權重及圓餅圖，再選擇子面向。'],['Total weight / Weight','類別權重／面向權重','表示目前評等計算中的權重；不能直接當作風險發生機率。'],['Weight: Up to','最高可達的權重','受入侵系統相關面向的合計影響上限，不應把每項上限相加。'],['A–F / N/A','等級／不適用','個別風險面向的呈現，不是整家公司分數。'],['Top / Bottom 10–50%','相對位置','與比較群體的分布位置，需連同資料範圍解讀。'],['* Does not impact rating','* 目前不影響評等','仍可作為調查資訊，但不計入目前資安評等。'],['** Informational risk vector','** 資訊性風險面向','資訊性線索，永遠不影響資安評等。'],['Variable weight','變動權重','公開揭露類別沒有固定權重，部分事件可能影響評等。'],['Toggle navigation','切換子選單','收合或展開頁內風險面向導覽。'],['Copy … to URL','複製面向連結','取得指定子面向的定位連結，方便分享頁面位置。']])}<h2>建議操作流程</h2><ol><li>在 Overview 比較四大類，留意權重高且等級較弱的面向。</li><li>從左側頁內導覽點選具體子面向；分辨是 <strong>評等構成項</strong>、標 * 的目前不計分項，或標 ** 的資訊性項目。</li><li>連到對應的發現事項與資產，確認觀測時間及資產歸屬，再決定是否優先改善。</li><li>若需向他人說明，用 Copy … to URL 定位子面向，並一併提供公司、資料日期與明細證據。</li></ol><div class="example"><strong>使用情境：決定先處理哪個風險面向</strong><p>若某個高權重面向等級偏低，可先調查該面向的具體發現。權重只是評等計算資訊；實際順序還需考慮弱點可利用性、資產重要性與內部控制狀態。</p></div><h2>容易誤判的地方</h2><ul><li><strong>高權重不等於已發生事故：</strong>它表示對評等的相對影響，仍需查證發現事項。</li><li><strong>不計分不等於沒風險：</strong>標 * 或 ** 的面向仍可能值得內部追蹤。</li><li><strong>相對位置不是絕對安全：</strong>Top／Bottom 會受比較群體影響。</li><li><strong>權重可能調整：</strong>原介面及評等演算法更新時，應以當前顯示為準，不把本文件範例數值視為固定規則。</li></ul><p class="note">依 2026-09-18 可見的 SPM 風險面向頁整理。中文為教學譯名，非官方譯文；評級、權重及相對位置依公司及時間而變。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="ratings-tree"><strong>評等樹</strong><small>Ratings Tree · 核對組織範圍。</small></button><button class="feature-card" data-page="findings-table"><strong>發現事項表格</strong><small>Findings Table · 查證具體問題。</small></button></div></article>`;
}

function ratingsTreePage() {
  return `<article class="doc"><button class="back-link" data-page="risk-vectors">← 返回風險面向</button><div class="eyebrow">組織 Organization / Ratings Tree</div><h1>評等樹</h1><p class="lead">Ratings Tree 以樹狀層級呈現目前公司及相關組織的評等。這和 CM 的評等樹使用相同核心概念；SPM 頁面另外可檢視訂閱、IP 數量、節點資訊與多種篩選條件。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Organization → Ratings Tree</code>。先確認頁首 <code>Ratings Tree for …</code> 的公司，再判讀根節點與子節點。</div><h2>樹狀圖與節點</h2>${docTable(['介面文字','建議中文','怎麼判讀'],[['Primary Rating','主要評等','標示目前組織的主要評等節點；與子節點分數區分。'],['Basic / Advanced','基礎／進階','評等呈現層級，不是風險嚴重度。'],['Low Confidence','低信心度','關聯可信度標記；應核對該節點是否真的屬於組織。'],['Private / Self-Published','私人／自行公開','評等的可見或發布性質，不等於分數高低。'],['View Company','查看公司','前往該節點的公司詳情。'],['Subscribed','已訂閱','表示該節點已納入目前訂閱。'],['Monitored by','受監控數','平台上監控該公司的數量，不代表公司風險。'],['IP addresses','IP 位址數','該節點顯示的網路資產規模；需核對歸屬。'],['Subscription','訂閱','此節點的訂閱類別，例如 My Company 或 My Subsidiary。'],['More Details','更多詳情','展開公司描述、網站與產業等背景資訊。'],['Expand content / collapse content','展開／收合節點','檢視或隱藏該節點底下的組織。']])}<h2>工具列</h2>${docTable(['英文','建議中文','功能'],[['Show Filters / Hide Filters','顯示／隱藏篩選器','開啟或關閉左側篩選面板。'],['search','搜尋','查找樹中的公司；篩選面板也有自己的搜尋欄。'],['Collapse All','全部收合','縮小整棵樹，先觀察高層結構。'],['Zoom Slider','縮放滑桿','調整樹狀圖比例。'],['Reset scroll location','重設捲動位置','回到預設視角。'],['Views / Create View','檢視／建立檢視','管理常用的篩選組合；建立前先核對條件。']])}<h2>篩選器對照</h2><p>可見的篩選面板含以下 16 類；具體選項依帳號、資料與權限不同。</p>${docTable(['英文','建議中文','何時使用'],treeFilters)}<h2>建議操作流程</h2><ol><li>確認頁首的根公司；先按 <strong>Collapse All</strong> 看主要層級，再逐層展開。</li><li>點選節點檢查資安評等、Primary Rating、訂閱類型、IP addresses 和 Low Confidence 標記。</li><li>對可疑或不熟悉的節點，用 <strong>More Details</strong> 查公司描述、產業及網站；必要時開 <strong>View Company</strong> 進一步驗證。</li><li>需要找特定群組時，使用 Folder、Security Rating、Risk Vector Grade 等篩選；若結果消失，先檢查既有篩選。</li><li>記錄比較時的根公司、子節點、篩選條件與日期，不把不同節點分數混成同一筆結果。</li></ol><div class="example"><strong>使用情境：核對低信心度資產群</strong><p>若某子節點標示 Low Confidence，先檢查名稱、公司描述與 IP 範圍，再與內部資產清單對照。不要直接將其風險或分數算進總公司結論。</p></div><h2>容易誤判的地方</h2><ul><li><strong>樹上的上下層不一定是法律股權關係：</strong>可能是評等或技術範圍的分組，需查證實際關係。</li><li><strong>子節點分數不是根公司的分數：</strong>比較時要清楚指出節點與評等類型。</li><li><strong>IP 數量不是資產確權：</strong>外部可觀測資料可能受時差或歸屬判斷影響。</li><li><strong>篩選後樹可能不完整：</strong>畫面隱藏的節點不代表已刪除。</li></ul><p class="note">依 2026-09-18 可見的 SPM 評等樹整理；不複製帳號內公司名稱、數值或網站資料。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="company-list"><strong>我的公司清單</strong><small>My Company List · 核對公司集合。</small></button><button class="feature-card" data-page="subsidiaries"><strong>子公司</strong><small>Subsidiaries · 檢查組織關係。</small></button></div></article>`;
}

function companyListPage() {
  return `<article class="doc"><button class="back-link" data-page="ratings-tree">← 返回評等樹</button><div class="eyebrow">組織 Organization / My Company List</div><h1>我的公司清單</h1><p class="lead">My Company List 是 SPM 中查找自身公司及子公司等受監控對象的表格。與 CM 的 Companies List 共用搜尋、篩選、欄位及匯出概念，但這裡的 Subscription Type 會呈現 SPM 組織身分。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Organization → My Company List</code>。頁首 <code>My Company List for …</code> 表示目前所屬公司；搜尋與多項篩選會影響結果數。</div><h2>畫面區塊</h2><ol><li><strong>左側 Filters：</strong>以資料夾、評等、產業、風險面向等條件縮小清單；Columns 與 Views 管理顯示欄位及儲存檢視。</li><li><strong>表格工具列：</strong>顯示符合條件的公司數，並提供 Reports、Actions、Search、Download as CSV 和全螢幕。</li><li><strong>結果表格：</strong>預設可見 Company、Security Rating、Trend、Subscription Type；每列可勾選或開啟 Company Actions。</li><li><strong>分頁：</strong>可調整每頁筆數，並用 Prev／Next 瀏覽。批次操作前應留意目前頁及篩選範圍。</li></ol><h2>欄位對照</h2><p>頁面預設顯示部分欄位；按 Columns 可見以下一般欄位。中文譯法與 CM 相同的欄位保持一致。</p>${docTable(['英文','建議中文','用途與判讀'],companyListColumns)}<h2>篩選器對照</h2><p>此頁與 Ratings Tree 可見同一組 16 類篩選入口；選項及結果依帳號資料不同。</p>${docTable(['英文','建議中文','何時使用'],treeFilters)}<h2>按鈕與工具</h2>${docTable(['英文','建議中文','功能'],[['Columns','欄位','新增或移除表格欄位；Company 是固定欄位。'],['Views / Create View','檢視／建立檢視','儲存經常使用的篩選與欄位組合。'],['Search','搜尋','在目前清單中查找公司。'],['Select All / Select row','全選／選取單列','選擇目前結果進行批次操作；先核對範圍。'],['Company Actions','公司操作','開啟單一公司的可用操作。'],['Reports / Actions','報表／操作','頁首或清單的操作入口；未選取公司時，部分清單動作可能停用。'],['Download as CSV','下載 CSV','匯出目前清單資料，須遵守內部資料處理規範。'],['Enter full screen','進入全螢幕','擴大表格檢視空間。'],['Prev / Next','上一頁／下一頁','瀏覽分頁結果。']])}<h2>建議操作流程</h2><ol><li>確認目前公司與結果數，檢查是否已套用 Folder、Views 或其他篩選。</li><li>輸入公司名稱搜尋；如需比較，加入 Security Rating、Trend、Primary Domain 及 Subscription Type 欄位。</li><li>用 My Company／My Subsidiary 及產業等條件區分不同對象，再點公司名稱進入詳細頁。</li><li>需要匯出或批次處理時，先核對勾選對象、可見結果與資料處理權限。</li></ol><div class="example"><strong>使用情境：找出需要檢查的子公司</strong><p>先用 Subscription Type 縮小至子公司，再觀察 Security Rating 和 Trend。對變化明顯者進入 Company Details，確認風險面向與具體發現；不要僅依列表分數決定處置。</p></div><h2>容易誤判的地方</h2><ul><li><strong>零筆結果不等於沒有公司：</strong>可能是已儲存的 View、Folder 或多重篩選造成。</li><li><strong>訂閱類型不是風險分類：</strong>My Company、My Subsidiary 描述關係或監控身分，不等於安全等級。</li><li><strong>Trend 不能取代目前分數：</strong>評等較高但持續下降的公司仍值得調查。</li><li><strong>CSV 可能含敏感組織資料：</strong>分享及保存須遵守組織規範。</li></ul><p class="note">依 2026-09-18 可見的 SPM 公司清單整理；本導覽不複製帳號中的公司名稱、數值或識別碼。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="subsidiaries"><strong>子公司</strong><small>Subsidiaries · 管理組織範圍。</small></button><button class="feature-card" data-page="company-details"><strong>公司詳情</strong><small>Company Details · 深入單一公司。</small></button></div></article>`;
}

function subsidiariesPage() {
  return `<article class="doc"><button class="back-link" data-page="company-list">← 返回我的公司清單</button><div class="eyebrow">組織 Organization / Subsidiaries</div><h1>子公司</h1><p class="lead">Subsidiaries 的 Organizational History Breakdown 以時間軸並列自身公司與子公司評等，方便找出哪個組織節點出現持續變化。它是趨勢比較頁，並非子公司法律關係的唯一證據。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Organization → Subsidiaries</code>。先看 <code>Last Updated</code> 和 <code>Companies 已顯示數／總數</code>，確認資料日期及目前顯示的節點數。</div><h2>畫面控制與圖例</h2>${docTable(['英文','建議中文','功能與判讀'],[['Organizational History Breakdown','組織歷史變化','按月份比較多個組織節點的指標。'],['Last Updated','最後更新','資料更新日期，不一定等同每筆事件日期。'],['Show All Subsidiaries','顯示所有子公司','切換是否展示更多子節點；未開啟時只看到部分公司。'],['Bitsight Rating','BitSight 資安評等','預設比較指標；選單亦可改成風險面向。'],['Zoom 6m / 1y','縮放至 6 個月／1 年','切換比較的時間範圍。'],['Export','匯出','輸出目前圖表或資料，需依組織規範保存。'],['Companies n / total','已顯示／總公司數','先確認顯示是否完整，避免以少數節點推論全部。'],['Today','今日','時間軸最右側的目前比較點。'],['Sort','排序','調整節點顯示順序。'],['Basic / Intermediate / Advanced','基礎／中階／進階','評等色階圖例，不是組織重要性層級。'],['View Subsidiary Improvement','查看子公司改善','前往子公司改善分析。']])}<h2>可選擇的比較指標</h2><p>除了 Bitsight Rating，指標選單也列出受入侵系統、預防性措施、使用者行為和公開揭露等風險面向。譯名與「風險面向」頁共用；切換指標時，應重新核對數值是分數還是等級。</p>${docTable(['類別','英文子項','用途'],vectorGroups.map(([en,zh,items]) => [zh+' '+en,items.map(item => item[0]).join('、'),'用於比較各組織在同一風險面向的變化；資料可用性因公司而異。']))}<h2>建議操作流程</h2><ol><li>確認 Last Updated、目前指標與時間範圍（6m 或 1y）。</li><li>看 Companies 的已顯示／總數；若要完整盤點，再考慮開啟 Show All Subsidiaries。</li><li>找出趨勢惡化或與其他節點差異大的公司，記下月份與公司名稱。</li><li>切到相關風險面向，確認變化是否集中在某個類別；再回公司詳情或發現事項查原因。</li><li>如需分享，匯出前核對是否包含敏感公司清單與分數。</li></ol><div class="example"><strong>使用情境：季度子公司風險回顧</strong><p>固定使用 1y 視角，先比較各子公司的評等變化。對分數下降的節點，改看相同期間的風險面向，再開啟 Company Details 核對發現事項與資產。報告中註明沒有顯示的節點及篩選條件。</p></div><h2>容易誤判的地方</h2><ul><li><strong>顯示數不等於總數：</strong>畫面可能只呈現部分子公司；先看 Companies n／total。</li><li><strong>不同指標不能直接比較：</strong>資安評等與單一風險面向的量尺和含義不同。</li><li><strong>時間範圍影響趨勢：</strong>6 個月與 1 年視角可能得出不同印象。</li><li><strong>樹狀關聯須查證：</strong>報告組織關係時仍應核對內部公司資料。</li></ul><p class="note">依 2026-09-18 可見的 SPM 子公司頁整理；本導覽不複製帳號中的公司名稱、數值或組織結構。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="assessments"><strong>評估</strong><small>Assessments · 查看評估資料。</small></button><button class="feature-card" data-page="subsidiary-improvement"><strong>子公司改善</strong><small>Subsidiary Improvement · 追蹤改善方向。</small></button></div></article>`;
}

function assessmentsPage() {
  return `<article class="doc"><button class="back-link" data-page="subsidiaries">← 返回子公司</button><div class="eyebrow">組織 Organization / Assessments</div><h1>評估</h1><p class="lead">Assessments 把選定框架或問卷的題目，對照 SPM 可觀測的 Risk Vectors，方便辨識可用外部訊號輔助審查的題目。它是對照與調查工具，不是認證、稽核或合規判定。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Organization → Assessments</code>。頁首會同時顯示目前框架與公司；切換框架或公司後，題目及對照結果都可能改變。</div><h2>畫面區塊與按鈕</h2>${docTable(['英文','建議中文','功能'],[['Switch Assessments','切換評估','改看其他框架或問卷，例如 NIST CSF、NIST SP 800-53、SIG、TISAX 等；具體清單依授權而異。'],['Download PDF','下載 PDF','匯出目前框架／公司範圍的評估報告。'],['Filters','篩選器','按 Section、Flags、Grades、Risk Vectors 或 Mapped Questions 縮小結果。'],['Active Filters / Applied filters','啟用／已套用篩選','檢查目前條件，避免誤以為只剩少量題目。'],['Clear All','清除全部','移除已套用篩選條件。'],['Views / Create View','檢視／建立檢視','保存常用的篩選組合。'],['Search','搜尋','尋找題目或控制項。'],['Download as CSV','下載 CSV','匯出清單資料；注意內容可能包含組織風險資訊。'],['Enter full screen','進入全螢幕','擴大表格閱讀空間。']])}<h2>表格欄位與專有名詞</h2>${docTable(['英文','建議中文','如何理解'],[['Section','章節','框架的大分類，例如 Access Control。'],['Sub-Section','子章節','章節下更細的主題。'],['Question ID','題目識別碼','框架控制項或問卷題目的代碼；跨版本比較須留意版本。'],['Question','題目','原框架或問卷的要求文字。'],['Risk Vectors','風險面向','與題目相關的外部可觀測風險類別；是對照關聯，不是控制已實施的證據。'],['Flag','標記','頁面提供的標記欄位；需依實際篩選選項判讀。'],['Mapped Questions','已對照題目','僅顯示能對應風險面向的題目；未對照不等於不重要。'],['Questions Mapped','題目對照比例','表示有多少題目被連到可觀測風險面向，不是符合率或通過率。'],['Grades','等級','可依相關評等資料縮小範圍，不能視為稽核結果。'],['Rows','資料列數','目前條件下顯示的結果數。']])}<h2>建議操作流程</h2><ol><li>確認頁首的公司、框架名稱與版本；如需比較，先固定這三個條件。</li><li>檢查 Applied filters；必要時先 Clear All，再選擇 Section 或 Question ID。</li><li>閱讀題目文字及 Risk Vectors 對照，評估哪些外部訊號能作為審查線索。</li><li>對關鍵題目，回到發現事項或風險面向頁核對公司資產與資料時間，並向內部控制負責人索取正式證據。</li><li>匯出 PDF／CSV 前確認框架版本、篩選條件和資料分享對象。</li></ol><div class="example"><strong>使用情境：準備控制項審查</strong><p>在 NIST SP 800-53 等框架中找出特定 Question ID，查看映射到 Open Ports、SSL Configurations 或其他 Risk Vectors 的外部線索。這可以幫助提出查證問題，但不能因為「100% of Questions Mapped」就宣稱 100% 合規。</p></div><h2>容易誤判的地方</h2><ul><li><strong>Mapped 不等於 Compliant：</strong>題目能對照到風險面向，只代表有可供參考的外部訊號。</li><li><strong>未對照不等於未實施：</strong>部分管理或流程控制無法用外部觀測驗證。</li><li><strong>框架版本會改變題目：</strong>同一題號在不同版本可能有不同要求。</li><li><strong>篩選會改變分母：</strong>題目數和對照比例須連同已套用條件一起報告。</li></ul><p class="note">依 2026-09-18 可見的 SPM 評估頁整理；本導覽不複製帳號內的評估結果、公司資訊或題目全文。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="breach"><strong>資料外洩情報</strong><small>Breach Intelligence · 查核事件線索。</small></button><button class="feature-card" data-page="risk-vectors"><strong>風險面向</strong><small>Risk Vectors · 理解對照來源。</small></button></div></article>`;
}

function breachPage() {
  return `<article class="doc"><button class="back-link" data-page="assessments">← 返回評估</button><div class="eyebrow">組織 Organization / Breach Intelligence</div><h1>資料外洩情報</h1><p class="lead">Breach Intelligence 彙整與目前公司或投資組合相關的公開揭露與威脅情報事件。先確認事件來源、日期、受影響公司與是否影響評等，再開啟明細查證。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Organization → Breach Intelligence</code>。結果受目前投資組合範圍與篩選條件影響；事件數不等於已證實遭入侵的公司數。</div><h2>總覽與事件卡片</h2>${docTable(['原介面文字','建議中文','功能與判讀'],[['All Events','所有事件','目前選定投資組合的事件總覽。'],['Public Disclosure','公開揭露','由公開報導或可信公開來源整理的事件。'],['Threat Intelligence*','威脅情報*','可能來自深網、暗網及公開網路監測；Potential 表示仍需驗證。'],['Impacted Companies','受影響公司','列出或顯示關聯公司的數量；需核對個別公司與範圍。'],['Date','日期','事件卡片列出的日期，注意與實際發生、揭露或觀測時間可能不同。'],['Event Type','事件類型','例如勒索軟體、DNS 問題或其他揭露。'],['Severity','嚴重度','用來排序調查順序，不能單獨判斷內部影響。'],['Verified','已核實標記','平台對事件資料的標示，仍需查看來源與自身影響。'],['Impacts Rating / Does Not Impact Rating','影響／不影響評等','說明這筆事件是否計入 BitSight 評等；不計分不代表無需處理。'],['View Details','查看詳情','開啟事件明細、來源與建議步驟。']])}<h2>篩選器對照</h2>${docTable(['英文','建議中文','用途'],[['Severity','嚴重度','找出需要優先審查的事件。'],['Event Type','事件類型','聚焦特定事件類別。'],['Rating Impact','評等影響','區分是否影響資安評等。'],['Source Type','來源類型','區分公開揭露與其他情報來源。'],['Countries','國家／地區','縮小事件涉及的地理範圍。'],['Industry','產業','檢視特定產業的事件。'],['Company','公司','限定相關公司。'],['Date','日期','設定事件時間區間。'],['Actor','威脅行為者','搜尋已標識的行為者。'],['APT','進階持續性威脅組織','依已標識的 APT 關聯篩選。'],['CVE','弱點編號','查找與已知弱點相關的事件。'],['Affected Products','受影響產品','依產品線索篩選。']])}<h2>事件詳情的區塊</h2>${docTable(['英文','建議中文','用途'],[['Source / Source Details','來源／來源詳情','查看原始連結和資料背景。'],['Adversary Details','對手資訊','檢查 Actor 與 APT；沒有資料時不要自行推定。'],['Exploited Vulnerabilities & Tooling','遭利用弱點與工具','檢查 CVE、惡意軟體家族與勒索軟體種類。'],['Compromised Data','受影響資料','查看資料外洩類型與活動分類；資料可能尚未完整。'],['Affected Products','受影響產品','辨識可能波及的產品。'],['Recommended Steps','建議步驟','作為內部調查與溝通參考，不能取代組織應變流程。'],['Download PDF / Download CSV','下載 PDF／CSV','輸出目前事件詳情或清單；先核對分享對象。']])}<h2>建議操作流程</h2><ol><li>確認 All Events、Public Disclosure 與 Threat Intelligence 的範圍；檢查已套用的日期和公司篩選。</li><li>依 Severity 和 Rating Impact 排序線索，但也留意不計分、卻可能影響業務的事件。</li><li>開啟 View Details，閱讀來源、事件描述、受影響公司、CVE／產品及事件日期。</li><li>將事件與內部日誌、資產清單或供應商回覆交叉驗證，再決定通知、改善或持續監看。</li><li>若需對外分享，引用原始來源並清楚區分「已確認事實」與「潛在情報」。</li></ol><div class="example"><strong>使用情境：新事件分流</strong><p>某事件出現在 Public Disclosure，先確認它是否真的涉及目前監控的公司與產品，再查看 Source Details 和相關 CVE。即使卡片標示 Verified，也不能直接推論自己的環境受影響。</p></div><h2>容易誤判的地方</h2><ul><li><strong>事件卡片是線索：</strong>同一事件可能關聯多家公司，不能把卡片數當作事故公司數。</li><li><strong>Potential 不等於已證實：</strong>威脅情報類別可能需要更多來源交叉驗證。</li><li><strong>不影響評等不等於無風險：</strong>應依業務、資料及資產實際影響判斷。</li><li><strong>No available information 不等於不存在：</strong>行為者或 CVE 欄位空白，只表示目前頁面沒有資料。</li></ul><p class="note">依 2026-09-18 可見的 SPM 資料外洩情報頁整理；本導覽不複製帳號內事件內容或公司資訊。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="badge"><strong>BitSight 徽章</strong><small>Bitsight Badge · 下一個組織主題。</small></button><button class="feature-card" data-page="findings-table"><strong>發現事項表格</strong><small>Findings Table · 查證公司風險。</small></button></div></article>`;
}

function badgePage() {
  return `<article class="doc"><button class="back-link" data-page="breach">← 返回資料外洩情報</button><div class="eyebrow">組織 Organization / Bitsight Badge</div><h1>BitSight 徽章</h1><p class="lead">Bitsight Badge 提供可嵌入網站的資安評等徽章與說明頁預覽。這涉及對外公開評等；變更分享設定或貼上嵌入碼前，應取得組織授權並確認網域。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Organization → Bitsight Badge</code>。本導覽只解釋功能，不會替你啟用分享、複製帳號專屬嵌入碼或修改允許網域。</div><h2>設定項目與介面翻譯</h2>${docTable(['英文','建議中文','功能與注意'],[['Enable Rating Sharing','啟用評等分享','控制是否允許對外展示；屬公開狀態變更，須事先核准。'],['Badges','徽章','設定網站嵌入式徽章的樣式與內容。'],['Landing Page','公開說明頁','預覽訪客看到的說明頁；可切換桌機、平板及手機尺寸。'],['Layout: Badge / Narrow / Wide','版型：徽章／窄版／寬版','調整嵌入內容的橫向配置。'],['Size: Large / Medium / Small','尺寸：大／中／小','調整徽章大小。'],['Embed Code','嵌入碼','帳號專屬的 HTML／Script 程式碼，供核准的網站使用。'],['COPY EMBED CODE','複製嵌入碼','把目前設定的嵌入碼複製到剪貼簿；貼上前須確認網站治理流程。'],['Badge configurations','徽章設定','選擇顯示的評等與比較資訊。'],['90-day Average','90 天平均','顯示過去 90 天平均評等，與當前評等不同。'],['Current Rating','目前評等','顯示當前評等；可能隨資料更新改變。'],['Show Industry Average','顯示產業平均','附上產業比較值，需確認比較範圍與資料日期。'],['Allowed Domains','允許的網域','限制哪些網站可使用嵌入碼；新增網域時使用完整 URL。'],['Save changes','儲存變更','正式套用設定；儲存前應檢查分享範圍及預覽。']])}<h2>使用前檢查</h2><ol><li>先取得資訊安全、法務或品牌團隊對公開評等的授權，確認可揭露的公司與數值範圍。</li><li>在 Badges 頁調整 Layout、Size、90-day Average 或 Current Rating，檢查預覽是否符合預期。</li><li>在 Landing Page 預覽 Desktop、Tablet、Mobile 的呈現；留意公開頁面的文字是否需要內部審核。</li><li>檢查 Allowed Domains 是否只有核准網站；不要把嵌入碼貼到非授權站點。</li><li>確認後才儲存變更及部署嵌入碼，並安排定期檢查徽章是否仍符合對外揭露政策。</li></ol><div class="example"><strong>使用情境：公司網站展示評等</strong><p>網站團隊先確認揭露政策和核准網域，再選擇顯示 90 天平均或目前評等。兩者不能混為同一數字；若顯示產業平均，頁面應保留來源與比較範圍說明。</p></div><h2>容易誤判的地方</h2><ul><li><strong>預覽不是授權：</strong>看得到徽章設定，不表示可對外發布。</li><li><strong>平均與目前值不同：</strong>90-day Average 可能與 Current Rating 有差異。</li><li><strong>嵌入碼與允許網域相關：</strong>在其他網域上可能無法顯示，亦不應繞過限制。</li><li><strong>評等會變動：</strong>公開網站需避免把當前分數表述成永久認證或合規證明。</li></ul><p class="note">依 2026-09-18 可見的 SPM 徽章頁整理；本文件不保存或顯示帳號專屬嵌入碼、允許網域或評等數值。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="findings-table"><strong>發現事項表格</strong><small>Findings Table · 下一個主題。</small></button><button class="feature-card" data-page="company-details"><strong>公司詳情</strong><small>Company Details · 核對評等來源。</small></button></div></article>`;
}

function findingsTablePage() {
  return `<article class="doc"><button class="back-link" data-page="badge">← 返回 BitSight 徽章</button><div class="eyebrow">發現事項 Findings / Findings Table</div><h1>發現事項表格</h1><p class="lead">Findings Table 是從 SPM 摘要走向具體證據的主要入口。先固定公司與篩選條件，再看風險面向、資產、觀測時間和評等影響，最後決定是否追蹤或要求重新掃描。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Findings → Findings Table</code>。頁首的 <code>Findings for …</code> 指出目前公司；若只看到 0 筆，先檢查 Active Filters、已儲存 Views 與快速篩選按鈕。</div><h2>表格欄位</h2>${docTable(['英文','建議中文','用途與判讀'],findingColumns)}<h2>左側篩選器</h2><p>這 11 類篩選可共同作用；條件越多，結果越窄。左側的 Active Filters／Applied filters 顯示目前生效的設定。</p>${docTable(['英文','建議中文','何時使用'],findingFilters)}<h2>快速檢視與工具列</h2>${docTable(['英文','建議中文','功能／注意'],[['Impacts RV Grade Only','僅看影響面向等級','快速聚焦會影響風險面向等級的發現。'],['Active Filters / Clear All','已套用條件／清除全部','檢查或重設目前篩選；清除前先記錄需要保留的條件。'],['Columns / Views / Create View','欄位／檢視／建立檢視','設定表格欄位並保存常用篩選。'],['Search','搜尋','在目前結果中找資產或發現。'],['Select All / Select row','全選／選取單列','進行批次操作前核對公司、條件和頁數。'],['Update Status','更新狀態','記錄發現處理狀態；屬會改動原系統資料的操作。'],['Rescan','重新掃描','要求重新檢查選定發現；可用性依權限與資料而異。'],['Rescan Notifications Dropdown','重新掃描通知選單','查看重新掃描的通知相關選項。'],['Comment','留言','在單筆發現留下協作紀錄。'],['download table data as','下載表格資料','匯出目前清單；注意資產及風險資訊敏感性。'],['Enter full screen','進入全螢幕','擴大表格閱讀空間。']])}<h2>建議操作流程</h2><ol><li>確認頁首公司，以及 Active Filters、Views 和快速檢視是否仍生效。</li><li>依 Finding Severity、Rating Impact、Assets 或 Last Seen 縮小範圍。</li><li>先讀 Risk Vector、Finding Identifier、Details、First Seen／Last Seen 和 Attributed To，判斷資產是否屬於此公司。</li><li>把 Impacts Risk Vector Grade、Asset Importance 與 Threat Insights 作為優先排序的輔助訊號，不只看單一分數。</li><li>確定需要處理後，依內部流程使用 Update Status、Comment 或 Rescan，並記錄負責人與驗證時間。</li></ol><div class="example"><strong>使用情境：追查新發現</strong><p>先清楚標記時間條件，找出最近首次觀測的發現；再核對最近觀測、資產歸屬、嚴重度與威脅資訊。若已修復，但 Last Seen 尚未更新，先確認資料更新節奏，再評估是否需要重新掃描。</p></div><h2>容易誤判的地方</h2><ul><li><strong>零筆結果不等於零風險：</strong>可能是多個篩選、檢視或公司範圍造成。</li><li><strong>First Seen 不等於問題起始日：</strong>只是平台首次觀測時間。</li><li><strong>Impacts Risk Vector Grade 與總評等不同：</strong>面向等級變化不一定立即等於公司總分變化。</li><li><strong>Remaining Lifetime 不是 SLA：</strong>不能把平台資料生命週期當成內部修復期限。</li><li><strong>Rescan 不是修復：</strong>重新檢查只更新觀測，真正的修補仍需由資產負責團隊完成。</li></ul><p class="note">依 2026-09-18 可見的 SPM 發現事項表格整理；本導覽不複製帳號中的資產、發現識別值或處理紀錄。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="issue-tracking"><strong>議題追蹤</strong><small>Issue Tracking · 追蹤處理進度。</small></button><button class="feature-card" data-page="vulnerability"><strong>弱點偵測</strong><small>Vulnerability Detection · 聚焦弱點訊號。</small></button></div></article>`;
}

function issueTrackingPage() {
  return `<article class="doc"><button class="back-link" data-page="findings-table">← 返回發現事項表格</button><div class="eyebrow">發現事項 Findings / Issue Tracking</div><h1>議題追蹤</h1><p class="lead">Issue Tracking 是發現事項的工作進度儀表板，用狀態、負責人、資產風險與處理預測協助追蹤改善；它顯示管理流程，不代表問題已在技術上修復。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Findings → Issue Tracking</code>。頁首的 <code>Issue Tracking for …</code> 指出目前公司；比較卡片前要先核對公司、卡片期間與 Select 條件。</div><h2>狀態名稱</h2>${docTable(['英文','建議中文','判讀'],[['No Status','未設定狀態','尚未分類，不代表安全或無需處理。'],['Open','未處理','問題仍開啟，尚未進入明確工作階段。'],['To Do','待處理','已排入工作，但尚未開始。'],['Work In Progress (WIP)','處理中','目前正在調查或改善。'],['Resolved','已解決','流程中已標記完成；仍要核對最新觀測或重新掃描結果。'],['Risk Accepted (RA)','已接受風險','經治理程序決定暫不改善，不等於弱點消失。']])}<h2>儀表板卡片</h2>${docTable(['原介面文字','建議中文','功能與使用情況'],[['Status Summary','狀態摘要','彙整各工作狀態及未設定狀態的數量。'],['To Do (Total)','待處理（總計）','查看已排程但尚未開始的發現。'],['Work In Progress (Total)','處理中（總計）','追蹤目前進行中的工作量。'],['Resolved (30 Days)','近 30 天已解決','查看近期標記完成的發現；期間可能依卡片設定不同。'],['Asset Risk Matrix (60 Days)','資產風險矩陣（60 天）','以 Asset Importance 與 Finding Severity 交叉呈現數量，協助找出重要資產上的嚴重發現。'],['Findings by Assignee (30 Days)','依負責人分類的發現（30 天）','依負責人及狀態比較工作分布；不宜單獨當成績效指標。'],['Finding Lifetime (180 Days)','發現事項生命週期（180 天）','比較 All Findings、Resolved Findings 與預計到期數量；這是資料生命週期，不是 SLA。'],['Resolved Findings (3 Months With Current Month)','近三個月已解決發現','顯示含本月的完成趨勢，可用 View All 進一步查看。'],['Remediation Forecasts','改善預測','呈現改善工作可能的後續走勢；屬估計，不是完成承諾。'],['Risk Accepted (Total)','已接受風險（總計）','集中檢查已接受風險的發現與治理依據。'],['Open (Total)','未處理（總計）','查看仍保持開啟的全部發現。']])}<h2>控制項與矩陣名詞</h2>${docTable(['英文','建議中文','功能／注意'],[['Reports','報表','從目前公司脈絡前往相關報表。'],['Actions','操作選單','顯示目前範圍可用的操作；內容依權限不同。'],['Edit Dashboard','編輯儀表板','調整卡片版面或內容。'],['Select','選擇','設定個別卡片的公司、期間或其他顯示範圍。'],['View All','查看全部','從摘要卡片進入完整清單。'],['Asset Importance','資產重要性','矩陣縱軸，分為 Critical、High、Medium、Low。'],['Finding Severity','發現嚴重度','矩陣橫軸，分為 Minor、Moderate、Material、Severe。'],['All Findings / Resolved Findings','所有發現／已解決發現','生命週期圖的系列；可用圖例辨識。']])}<h2>建議操作流程</h2><ol><li>確認公司與每張卡片的期間、Select 條件，避免拿不同範圍的數字互相比較。</li><li>先看 Status Summary，特別檢查 No Status、Open 與逾期未動的工作。</li><li>在 Asset Risk Matrix 優先檢查重要資產上的 Material／Severe 發現，點擊數量回到發現事項明細。</li><li>用 Findings by Assignee 檢查責任歸屬與工作分布，再回到單筆證據判斷優先序。</li><li>用 Finding Lifetime、Resolved Findings 與 Remediation Forecasts 觀察趨勢；不能把預測或資料到期視為修復完成。</li><li>狀態要變更時，依內部治理流程在發現事項明細記錄負責人、證據與驗證結果。</li></ol><div class="example"><strong>使用情境：每週改善會議</strong><p>先固定公司與期間，檢查未設定狀態及高重要性資產上的嚴重發現，再按負責人確認卡點。對已解決與已接受風險的項目，要分別檢查重新觀測結果與核准依據。</p></div><h2>容易誤判的地方</h2><ul><li><strong>卡片數字受條件影響：</strong>不同期間或 Select 設定不能直接相減。</li><li><strong>Risk Accepted 不是 Resolved：</strong>前者保留風險並記錄決策，後者表示處理流程已完成。</li><li><strong>Resolved 不一定立即從觀測消失：</strong>仍可能受重新掃描或資料更新節奏影響。</li><li><strong>Finding Lifetime 不是修復期限：</strong>平台資料生命週期不能取代內部 SLA。</li><li><strong>負責人圖不是績效排行榜：</strong>工作量還會受嚴重度、資產範圍及案件複雜度影響。</li></ul><p class="note">依 2026-09-21 可見的 SPM 議題追蹤頁整理；本導覽不複製帳號中的公司、負責人或工作數量。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="vulnerability"><strong>弱點偵測</strong><small>Vulnerability Detection · 查看弱點與受影響資產。</small></button><button class="feature-card" data-page="risk-remediation"><strong>風險改善</strong><small>Risk Remediation · 規劃及驗證改善。</small></button></div></article>`;
}

function vulnerabilityPage() {
  return `<article class="doc"><button class="back-link" data-page="issue-tracking">← 返回議題追蹤</button><div class="eyebrow">發現事項 Findings / Vulnerability Detection</div><h1>弱點偵測</h1><p class="lead">Vulnerability Detection 以 CVE 為主彙整外部觀測到的弱點線索，並結合 CVSS、DVE、EPSS、威脅情報與證據可信度協助排序。任何單一欄位都不能獨立證明資產可被利用。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Findings → Vulnerability Detection</code>。結果屬於頁首目前選取的公司；先檢查 Filters、Views 與排序，再解讀總筆數。</div><h2>表格欄位</h2>${docTable(['英文','建議中文','功能與判讀'],[['Vulnerability','弱點','通常顯示 CVE 識別碼；點入後再確認描述、產品和受影響資產。'],['Severity Details','嚴重度詳情','顯示 CVSS 分數；Critical 9.0–10.0、High 7.0–8.9、Medium 4.0–6.9、Low 0.0–3.9。'],['DVE Score','動態弱點可利用性分數','以動態情報輔助判斷可利用性；與 CVSS 的技術嚴重度不同。'],['CTI Attributes','網路威脅情報屬性','可能顯示 POC Exploit、Anonymous 等情報標記；需核對其具體定義與時效。'],['EPSS','漏洞遭利用預測分數','以百分比呈現被利用可能性的預測訊號，不是環境已遭利用的證據。'],['Statement','聲明','組織對弱點狀況所記錄的說明，例如尚未建立聲明。'],['Detection','偵測類型','說明此列的辨識方式；目前介面可見 Exposure。'],['Evidence Certainty','證據確信度','例如 Likely；表示證據判斷強度，不等於已完成內部驗證。'],['Evidence Available','可用證據','列出可佐證或反駁的訊號，例如 Version in use、Mitigation applied。'],['First Seen','首次觀測','平台第一次看到此弱點訊號的日期。'],['Last Seen','最近觀測','平台最近一次看到此弱點訊號的日期；不是修補完成日。'],['Set Statement','設定聲明','為單筆或選定弱點記錄組織說明；會改動原系統資料。'],['View History','查看歷程','查看該弱點聲明或狀態的過往紀錄。']])}<h2>篩選器</h2>${docTable(['英文','建議中文','何時使用'],[['Group','群組','依可用的弱點群組縮小結果。'],['Severity','嚴重度','依 CVSS 區間篩選 Critical、High、Medium、Low。'],['DVE Score','DVE 分數','聚焦動態可利用性較高或特定分數區間。'],['CTI Attributes','威脅情報屬性','找有 POC、匿名利用等情報標記的弱點。'],['EPSS','EPSS','依預測遭利用機率縮小範圍。'],['First Seen','首次觀測','找新出現或指定期間首次觀測的項目。'],['Last Seen','最近觀測','檢查近期仍被觀測到的弱點。'],['Evidence Certainty','證據確信度','依證據判斷強度篩選。'],['Evidence Available','可用證據','依版本、緩解措施或其他可用訊號篩選。'],['Detection','偵測類型','依辨識方式區分結果。'],['Statement','聲明','找尚未聲明或特定聲明狀態的弱點。'],['Statement Visibility','聲明可見性','檢查聲明的分享範圍。']])}<h2>工具列與操作</h2>${docTable(['介面文字','建議中文','功能／注意'],[['Vulnerabilities Reports','弱點報表','從目前弱點脈絡選擇報表。'],['Columns','欄位','調整表格顯示欄位。'],['Views / Create View','檢視／建立檢視','載入或保存常用篩選和欄位設定。'],['Search','搜尋','查找 CVE 或目前清單中的資料。'],['0 Selected','已選取 0 筆','顯示目前選取數量；批次處理前先核對範圍。'],['Set Statement (n)','設定聲明（n 筆）','為選取項目批次記錄聲明，須依治理流程執行。'],['View Advanced Threat Intel','查看進階威脅情報','前往更深入的弱點情報產品或頁面；可用性依授權而異。'],['Download as CSV','下載 CSV','匯出目前清單；注意弱點與資產資料的分享規範。'],['Enter full screen','進入全螢幕','放大表格閱讀區域。'],['Column options','欄位選項','對單一欄位進行排序或可用設定。']])}<h2>建議操作流程</h2><ol><li>確認公司、總筆數、現有 Views、Filters 和排序條件。</li><li>先用 Severity、DVE Score、CTI Attributes、EPSS 與 Last Seen 建立候選清單，不要只按 CVSS 排序。</li><li>打開 CVE 明細，核對受影響產品、版本、資產歸屬、偵測方式與證據確信度。</li><li>將外部訊號與內部 CMDB、掃描器、EDR 或修補紀錄交叉驗證，確認實際暴露與可利用性。</li><li>需要 Set Statement 時，記錄判斷依據、驗證日期和可見範圍；修補後持續確認 Last Seen 是否更新。</li></ol><div class="example"><strong>使用情境：排定修補優先序</strong><p>先找近期仍可見、CVSS 高且同時具有較高 DVE／EPSS 或明確 CTI 屬性的弱點，再確認重要資產是否真的使用受影響版本。優先序應結合資產重要性與補償控制，而不是單靠一個分數。</p></div><h2>容易誤判的地方</h2><ul><li><strong>CVSS、DVE 與 EPSS 不同：</strong>分別描述技術嚴重度、動態可利用性與遭利用預測，不能互相替代。</li><li><strong>Exposure 不等於成功利用：</strong>外部可見訊號仍需內部證據驗證。</li><li><strong>Likely 不是 Confirmed：</strong>Evidence Certainty 表示確信程度，不是最終事實認定。</li><li><strong>Mitigation applied 不一定代表已修補：</strong>可能有補償控制，仍要檢查版本與實際暴露。</li><li><strong>No Statement 不等於未處理：</strong>它只代表平台中尚無聲明紀錄。</li></ul><p class="note">依 2026-09-21 可見的 SPM 弱點偵測頁整理；本導覽不複製帳號內的 CVE 清單、分數、資產或聲明。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="infrastructure"><strong>基礎設施</strong><small>Infrastructure · 核對受影響資產歸屬。</small></button><button class="feature-card" data-page="risk-remediation"><strong>風險改善</strong><small>Risk Remediation · 安排修補與驗證。</small></button></div></article>`;
}

function infrastructurePage() {
  return `<article class="doc"><button class="back-link" data-page="vulnerability">← 返回弱點偵測</button><div class="eyebrow">攻擊面 Attack Surface / Infrastructure</div><h1>基礎設施</h1><p class="lead">Infrastructure 用來核對 BitSight 歸屬於目前公司的外部資產、資料來源與有效期間。先確認 Attribution，再到 Assets、Change Log 與 Company Provided Assets 交叉檢查資產是否完整且歸屬正確。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Attack Surface → Infrastructure</code>。頁首的 <code>Infrastructure for …</code> 指出目前公司；新增、自行發布或要求移除資產都會影響平台資料，須先依內部資產治理流程確認。</div><h2>四個分頁</h2>${docTable(['英文','建議中文','功能與使用情況'],[['Attribution','歸屬資料','目前畫面；檢查 IP／網段如何被歸屬、來源、有效期間及所屬公司。'],['Assets','資產','從資產實體角度查看網域、主機或其他外部資產及其資訊。'],['Change Log','變更紀錄','追蹤基礎設施範圍的加入、移除或其他變更。'],['Company Provided Assets','公司提供的資產','查看由公司提交、待處理或已處理的資產要求。']])}<h2>Attribution 表格欄位</h2>${docTable(['英文','建議中文','用途與判讀'],[['Value','值','資產或網段值，例如 IP；屬敏感資產資料。'],['Source','來源','歸屬資料的來源，例如 Customer-Provided、ARIN 或 DNS。'],['Tags','標籤','以自訂標籤分類資產；標籤不是歸屬證明。'],['Grace Period','寬限期','指出資產是否在寬限期內；應連同結束日期判讀。'],['Grace Period End Date','寬限期結束日','寬限期預計結束日期。'],['Guest Network Exclusion','訪客網路排除','指出是否以訪客網路規則排除；不代表資產已移除。'],['Guest Network Exclusion End Date','訪客網路排除結束日','訪客網路排除的預計結束日期。'],['Country','國家／地區','平台判定的地理資訊，可能受 IP 登記或定位資料影響。'],['Start Date','開始日期','此歸屬紀錄的生效或開始時間。'],['End Date','結束日期','紀錄停止有效的日期；空白通常需配合 Is Active 判讀。'],['Is Active','是否有效','目前是否仍列為有效基礎設施。'],['Attributed To','歸屬公司','此資產目前歸屬的公司或組織節點。'],['AS Number','自治系統編號','網路路由所屬 AS 的識別編號。'],['CIDR Size','CIDR 大小','網段所涵蓋的位址數量或範圍大小。']])}<h2>篩選與操作</h2>${docTable(['介面文字','建議中文','功能／注意'],[['Only Active / Is Active','僅有效／是否有效','預設可能只顯示有效紀錄；零筆或數量差異時先檢查此條件。'],['Type','類型','依資產或歸屬類型縮小清單。'],['Source','來源','區分公司提供、註冊資料或 DNS 等來源。'],['Tags','標籤','依既有資產標籤篩選。'],['Grace Period / End Date','寬限期／結束日','找處於寬限期或即將結束的紀錄。'],['Country','國家／地區','依地理資訊篩選。'],['Guest Network Exclusion / End Date','訪客網路排除／結束日','檢查訪客網路排除及期限。'],['Start Date / End Date','開始日／結束日','依歸屬紀錄有效期間篩選。'],['Attributed To','歸屬公司','限定組織節點。'],['Manage Tags','管理標籤','建立或維護標籤；會改動帳號設定。'],['Add Assets','新增資產','提交資產加入要求；必須先驗證所有權與範圍。'],['Self-Publish','自行發布','依平台流程提交可自行發布的資產資料；屬資料變更。'],['Tag (n)','標記（n 筆）','批次套用標籤。'],['Request Removal (n)','要求移除（n 筆）','提交資產移除請求；先保存證據並確認影響。'],['Columns / Views / Create View','欄位／檢視／建立檢視','調整或保存表格呈現。'],['Download as CSV','下載 CSV','匯出目前清單；注意外部資產資訊敏感性。']])}<h2>建議操作流程</h2><ol><li>確認頁首公司、Attribution 分頁、Only Active 與排序條件。</li><li>檢查 Value、Source、Attributed To、Start／End Date 與 Is Active，辨別資產來源和有效期間。</li><li>對異常或陌生資產，到 Assets 查看細節，再以 Change Log 追查何時及為何出現。</li><li>將外部觀測與 CMDB、DNS、雲端帳號及網路管理資料交叉驗證。</li><li>確定歸屬不正確後，才依治理程序使用 Request Removal；缺漏資產則由 Add Assets 或 Company Provided Assets 處理。</li></ol><div class="example"><strong>使用情境：出現陌生 IP</strong><p>先看 Source 與 Attributed To，確認是否由公司提交、網路註冊或 DNS 線索歸屬；再到 Change Log 查日期，並與內部 IPAM／雲端資產清單核對。不要只因不認得 IP 就立即要求移除。</p></div><h2>容易誤判的地方</h2><ul><li><strong>外部歸屬不是所有權定論：</strong>Source 與時間資料仍需內部紀錄佐證。</li><li><strong>Inactive 不等於不存在：</strong>它表示目前歸屬紀錄非有效狀態，歷史風險仍可能需要查核。</li><li><strong>Grace Period 不是無風險：</strong>只是平台處理或評等影響的期間設定。</li><li><strong>Guest Network Exclusion 不是刪除：</strong>資產仍可能出現在基礎設施資料中。</li><li><strong>Request Removal 會影響資料範圍：</strong>送出前應確認資產、公司及證據。</li></ul><p class="note">依 2026-09-21 可見的 SPM Infrastructure／Attribution 頁整理；本導覽不複製帳號內 IP、網段、標籤或公司資料。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="surface-analytics"><strong>攻擊面分析</strong><small>Attack Surface Analytics · 從資產角度分析暴露。</small></button><button class="feature-card" data-page="probable"><strong>可能相關的基礎設施</strong><small>Probable Infrastructure · 驗證候選資產。</small></button></div></article>`;
}

function surfaceAnalyticsPage() {
  return `<article class="doc"><button class="back-link" data-page="infrastructure">← 返回基礎設施</button><div class="eyebrow">攻擊面 Attack Surface / Attack Surface Analytics</div><h1>攻擊面分析</h1><p class="lead">Attack Surface Analytics 將外部資產依託管、地區、產品、服務及子公司切分，並把資產分布和重大／嚴重發現並列，協助找出需要深入盤點的攻擊面。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Attack Surface → Attack Surface Analytics</code>。頁面可能包含目前公司在 Ratings Tree 下的子公司資產，因此解讀前先確認公司層級與評等樹範圍。</div><h2>主要分析卡片</h2>${docTable(['原介面文字','建議中文','功能與使用情況'],[['Hosting Distribution','託管分布','查看資產分布於哪些託管環境或組織。'],['Top Regions','主要地區','快速辨識資產最集中的地理區域。'],['AI Products','AI 產品','查看外部資產上辨識出的 AI 相關產品線索。'],['Risky Services','高風險服務','找出可能增加攻擊面的對外服務。'],['Attack Surface Exposure','攻擊面暴露','顯示近 60 天證據紀錄數最多的前 30 個弱點；泡泡越大表示證據紀錄越多。'],['External Hosting Organization Footprint','外部託管組織版圖','按外部託管組織比較 Asset Importance。'],['External Hosting Organization Asset Security','外部託管組織資產安全','按外部託管組織比較 Material／Severe Findings。'],['Subsidiary Footprint','子公司版圖','按子公司比較資產重要性。'],['Subsidiary Asset Security','子公司資產安全','按子公司比較重大／嚴重發現。'],['Product Footprint','產品版圖','按產品比較資產重要性。'],['Products Security','產品安全','統計使用不再受支援軟體版本的資產。'],['Geographic Footprint','地理版圖','按地理位置查看資產數量。'],['Geographic Security','地理安全','按地區比較重大／嚴重發現數。'],['Services Footprint','服務版圖','按服務類別查看資產數量。'],['Services Security','服務安全','統計存在重大／嚴重開放連接埠的資產。']])}<h2>圖表名詞與控制</h2>${docTable(['英文','建議中文','判讀方式'],[['Display Confirmed Only','僅顯示已確認','切換只看確認程度較高的暴露；切換前後總數不可直接混用。'],['Severe / Material / Moderate','嚴重／重大／中度','Attack Surface Exposure 圖中的嚴重程度系列。'],['Evidence records','證據紀錄','近 60 天與弱點相關的觀測紀錄數，不等於受影響資產數或成功利用次數。'],['Asset Importance','資產重要性','按 Critical、High、Medium、Low 等級呈現業務重要程度。'],['Material/Severe Findings','重大／嚴重發現','用於比較分群的高影響發現數量。'],['Reports','報表','從目前公司脈絡前往相關分析報表。'],['Actions','操作選單','顯示目前頁面可用的動作；內容依權限不同。'],['ratings tree','評等樹','查看本頁可能涵蓋的子公司與組織層級。']])}<h2>建議操作流程</h2><ol><li>確認目前公司，以及頁面是否包含 Ratings Tree 中的子公司資產。</li><li>先用 Hosting Distribution、Top Regions、Product／Services Footprint 了解資產集中位置。</li><li>把相同分群的 Footprint 與 Security 卡片配對，找出資產不多但重大發現偏高的區域。</li><li>在 Attack Surface Exposure 比較嚴重度、證據紀錄數和 Confirmed Only 切換結果，再進入 CVE／發現明細。</li><li>回到 Infrastructure 核對資產歸屬，並以內部 CMDB、雲端清單及業務重要性決定處理順序。</li></ol><div class="example"><strong>使用情境：尋找風險集中區</strong><p>若某外部託管組織的資產占比不高，卻有較多 Material／Severe Findings，應先確認那些資產是否真的屬於目前公司，再檢查產品版本、開放服務與具體證據。</p></div><h2>容易誤判的地方</h2><ul><li><strong>資產數不等於風險：</strong>規模大的群組自然可能有較多發現，需同時看占比與嚴重度。</li><li><strong>證據紀錄數不等於弱點數：</strong>同一弱點可能有多筆證據。</li><li><strong>地理位置可能是託管位置：</strong>不一定代表公司營運據點或資料所在地。</li><li><strong>產品辨識是外部線索：</strong>仍需內部軟體清單驗證版本及實際用途。</li><li><strong>Confirmed Only 會改變範圍：</strong>比較前要記錄切換狀態與資料期間。</li></ul><p class="note">依 2026-09-21 可見的 SPM 攻擊面分析頁整理；本導覽不複製帳號內的資產、弱點、地區或產品統計。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="work-from-home"><strong>居家辦公</strong><small>Work from Home · 檢視遠距辦公暴露。</small></button><button class="feature-card" data-page="infrastructure"><strong>基礎設施</strong><small>Infrastructure · 驗證資產歸屬。</small></button></div></article>`;
}

function workFromHomePage() {
  return `<article class="doc"><button class="back-link" data-page="surface-analytics">← 返回攻擊面分析</button><div class="eyebrow">攻擊面 Attack Surface / Work from Home</div><h1>居家辦公</h1><p class="lead">Work From Home – Remote Office（WFH）可查詢疑似居家辦公 IP 的外部安全訊號，以協助調查與規劃改善。這不是員工裝置管理或內部弱點掃描，輸入 IP 前應先遵守隱私及授權規範。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Attack Surface → Work from Home</code>。此頁可逐筆搜尋或上傳 CSV；查詢資料的蒐集、保存與使用方式應先閱讀 WFH Privacy Notice。</div><h2>頁面區塊與限制</h2>${docTable(['原介面文字','建議中文','功能與注意'],[['Work From Home - Remote Office','居家辦公－遠端辦公室','針對疑似有安全問題的居家辦公 IP 提供外部可見性。'],['Search for IP Addresses','搜尋 IP 位址','在文字區每行輸入一個 IPv4 位址。'],['0/50 IP Addresses','0／50 個 IP 位址','單次最多搜尋 50 個 IP。'],['SEARCH','搜尋','送出目前輸入的 IP 查詢。'],['File Upload','檔案上傳','以 CSV 批次提交 IP 查詢。'],['SELECT FILE','選擇檔案','選取符合格式與大小限制的 CSV。'],['Supported format: CSV','支援格式：CSV','需有一欄名為 IP Address，檔案上限 1 MB。'],['Previous Uploads','過往上傳','查看先前上傳作業與結果；頁面可能顯示 No previous uploads。'],['No support for IPv6 Addresses','不支援 IPv6 位址','目前文字搜尋與檔案上傳皆不支援 IPv6。'],['File upload searches may take up to 1 hour','上傳查詢可能需要最長一小時','批次結果不是即時產生，需稍後回來查看。'],['Bitsight Academy','BitSight 學院','前往產品學習資源。'],['Knowledge Base','知識庫','查看 WFH 功能說明與操作文件。'],['WFH Privacy Notice','WFH 隱私權聲明','了解查詢資料如何蒐集、保存及使用。']])}<h2>建議操作流程</h2><ol><li>先確認調查目的、IP 的合法來源，以及組織對員工或遠端網路資料的授權與隱私規範。</li><li>少量查詢時每行輸入一個 IPv4，最多 50 筆；大量查詢使用一欄標題為 <strong>IP Address</strong> 的 CSV。</li><li>提交前移除無關欄位與個人資料，並再次確認沒有 IPv6、格式錯誤或超過 1 MB。</li><li>檔案上傳後到 Previous Uploads 查看作業狀態；最長可能需要一小時。</li><li>將結果視為外部調查線索，與 VPN、EDR、資產及內部事件資料交叉驗證後才安排改善。</li></ol><div class="example"><strong>使用情境：遠端辦公異常調查</strong><p>安全團隊取得經授權的一批遠端出口 IPv4，先整理成最小必要的 CSV，再查詢外部安全訊號。若出現疑似問題，仍要用內部遙測確認對應時間、裝置及實際影響。</p></div><h2>容易誤判的地方</h2><ul><li><strong>IP 不一定對應單一員工或裝置：</strong>NAT、動態位址及共用網路會影響歸屬。</li><li><strong>外部訊號不是感染定論：</strong>需與內部證據及觀測時間交叉確認。</li><li><strong>沒有結果不代表安全：</strong>可能受資料可見性、期間或 IP 變更影響。</li><li><strong>上傳成功不等於查詢完成：</strong>批次作業可能需等待最長一小時。</li><li><strong>隱私優先：</strong>不可上傳未經授權或超出調查目的的個人資料。</li></ul><p class="note">依 2026-09-21 可見的 SPM Work From Home 頁整理；本導覽不輸入、保存或展示任何員工或居家網路 IP。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="cloud-sync"><strong>雲端基礎設施同步</strong><small>Cloud Infrastructure Sync · 納管雲端資產。</small></button><button class="feature-card" data-page="infections"><strong>感染事件</strong><small>Infections · 核對感染訊號。</small></button></div></article>`;
}

function cloudSyncPage() {
  return `<article class="doc"><button class="back-link" data-page="work-from-home">← 返回居家辦公</button><div class="eyebrow">攻擊面 Attack Surface / Cloud Infrastructure Sync</div><h1>雲端基礎設施同步</h1><p class="lead">Cloud Infrastructure Sync 透過一次性連線設定，自動把公有雲 IP 納入 BitSight 公司範圍，補足單靠 WHOIS、BGP、DNS 等外部資料可能難以發現的資產。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Attack Surface → Cloud Infrastructure Sync</code>。新增連線會授權平台讀取雲端資產；必須使用核准帳號、最小必要權限並由雲端管理員依內部流程設定。</div><h2>支援的雲端連線</h2>${docTable(['英文','建議中文','功能與注意'],[['Amazon Web Services (AWS)','Amazon Web Services（AWS）','建立 AWS 雲端資產同步連線。'],['Microsoft Azure','Microsoft Azure','建立 Azure 雲端資產同步連線。'],['Google Cloud Provider (GCP)','Google Cloud Platform（GCP）','建立 GCP 雲端資產同步連線；原介面顯示 Google Cloud Provider。'],['Add Connection','新增連線','進入該供應商的設定流程；會涉及雲端授權與帳號資訊。'],['Read more','閱讀更多','開啟 Cloud Infrastructure Sync 知識庫文章。']])}<h2>同步目的與資料時程</h2>${docTable(['原介面說明','建議中文與判讀'],[['One-time setup','一次性設定後，雲端 IP 可自動更新至 BitSight 公司。'],['Setup takes about 30 minutes','設定約需 30 分鐘，並需要雲端供應商的管理員角色；實際時間依環境與核准流程而異。'],['Ratings available 3 to 4 days after initial setup','首次自助設定後，同步評等約 3–4 天可用。初次設定時 IP 需連續兩天被觀測，之後再一天產生評等。'],['60-day grace period','新同步資產在影響評等前有 60 天寬限期；寬限期不代表沒有安全風險。'],['Scanned multiple times a day','平台每日多次掃描，畫面反映過去 48 小時內的變更；不是即時 CMDB。'],['Reporting, analytics and forensics','可對雲端基礎設施使用報表、分析與鑑識相關評等功能。'],['Compare cloud and non-cloud hosted performance','可比較雲端與非雲端託管，以及不同雲端供應商的表現。']])}<h2>設定前檢查</h2><ol><li>確認要同步的公司、雲端供應商、帳號／訂閱／專案及預期資產範圍。</li><li>由雲端與資安團隊審核所需角色及權限，採用專用身分和最小必要權限。</li><li>建立連線前記錄負責人、用途、變更單、撤銷方式及憑證輪替政策。</li><li>設定後等待初始同步，對照雲端資產清單與 Infrastructure，檢查缺漏、重複及錯誤歸屬。</li><li>在 60 天寬限期內優先處理新增發現，並持續監看近 48 小時的資產變動。</li></ol><div class="example"><strong>使用情境：納管新雲端帳號</strong><p>建立連線前先界定要納入的 AWS 帳號、Azure 訂閱或 GCP 專案，並確認只授予文件要求的讀取權限。同步後不能只看是否出現資產，還要核對它們被歸到正確公司與標籤。</p></div><h2>容易誤判的地方</h2><ul><li><strong>同步不是即時：</strong>首次評等約需 3–4 天，日常變更也以近 48 小時資訊呈現。</li><li><strong>寬限期不是安全緩衝：</strong>60 天只是評等影響時程，問題仍應及早改善。</li><li><strong>連線成功不等於範圍正確：</strong>仍需與雲端原生清單核對帳號、區域及資產。</li><li><strong>管理員角色需審慎使用：</strong>設定過程可能需要管理權限，但長期權限應依官方文件與最小權限原則配置。</li><li><strong>同步不取代雲端治理：</strong>仍需 CSPM、設定管理、日誌及內部資產管理。</li></ul><p class="note">依 2026-09-21 可見的 SPM Cloud Infrastructure Sync 頁整理；本導覽不建立連線，也不保存雲端帳號或憑證。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="probable"><strong>可能相關的基礎設施</strong><small>Probable Infrastructure · 審查候選資產。</small></button><button class="feature-card" data-page="infrastructure"><strong>基礎設施</strong><small>Infrastructure · 核對同步結果。</small></button></div></article>`;
}

function probablePage() {
  return `<article class="doc"><button class="back-link" data-page="cloud-sync">← 返回雲端基礎設施同步</button><div class="eyebrow">攻擊面 Attack Surface / Probable Infrastructure</div><h1>可能相關的基礎設施</h1><p class="lead">Probable Infrastructure 提供可能與組織相關、但信心較低且尚未歸屬的資產建議。候選項目必須由使用者獨立審查並主動要求加入，不會自動納入公司基礎設施。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Attack Surface → Probable Infrastructure</code>。Request Asset Suggestions 會建立新的候選資產請求；送出前須確認公司、需求與負責人。</div><h2>請求清單欄位</h2>${docTable(['英文','建議中文','功能與判讀'],[['Probable Infrastructure Requests','可能相關基礎設施請求','查看歷次候選資產建議請求及狀態。'],['Request Asset Suggestions','請求資產建議','為選定公司提出新一輪候選資產請求。'],['Company','公司','本次請求所屬的公司。'],['Requested On','請求時間','送出資產建議請求的日期與時間。'],['Expires On','到期日','本輪建議可供審查的到期日期。'],['Requested By','請求人','建立該請求的帳號。'],['Status','狀態','例如 Success 或 Expired；成功只表示請求完成，不代表建議已加入。'],['Success','成功','請求已產生可審查結果。'],['Expired','已到期','此輪建議已超過可用期間。']])}<h2>運作規則與操作詞彙</h2>${docTable(['原介面文字','建議中文與注意'],[['Independent Review & Action','獨立審查與操作：候選資產不會自動歸屬；需主動要求加入。'],['Good Suggestion','良好建議：回饋候選合理，但不會把資產加入基礎設施。'],['Bad Suggestion','不良建議：回饋候選不相關，協助改善後續模型建議。'],['60-day grace period','加入的公司提供資產預設有 60 天寬限期，可先檢查發現或 CVE，期間不影響評等。'],['Infrastructure expires after 60 days','候選基礎設施在 60 天後到期，應在期限內完成查核。'],['Request again after 30 days','前次請求 30 天後，可為同一公司再請求一組建議。'],['Learn more / Knowledge Base Resource','閱讀更多／知識庫資源：查看官方規則與最新限制。']])}<h2>建議操作流程</h2><ol><li>確認要調查的公司與前次請求日期，避免重複或過早建立請求。</li><li>使用 Request Asset Suggestions 後，記錄 Requested On、Expires On、Requested By 與 Status。</li><li>對每個候選資產核對 DNS、WHOIS／RIR、憑證、雲端帳號、CMDB 和業務擁有者。</li><li>Good／Bad Suggestion 只用於回饋建議品質；確認所有權後才另行要求加入。</li><li>資產加入後，在 60 天寬限期內檢查風險並修正錯誤歸屬，不能等到影響評等才處理。</li></ol><div class="example"><strong>使用情境：發現疑似遺漏網域</strong><p>候選網域名稱與公司相似時，先查註冊資料、DNS、憑證及內部應用負責人。只有多項證據一致且取得確認後，才要求加入；名稱相似本身不足以證明所有權。</p></div><h2>容易誤判的地方</h2><ul><li><strong>Probable 不是 Confirmed：</strong>候選資產的信心較低，尚未正式歸屬。</li><li><strong>Good Suggestion 不會加入資產：</strong>它是模型品質回饋，不是納管操作。</li><li><strong>Success 不代表資產已核准：</strong>只表示請求作業成功產生建議。</li><li><strong>60 天寬限期不等於沒風險：</strong>期間只是暫不影響評等，仍須立即調查。</li><li><strong>到期不代表候選錯誤：</strong>Expired 只表示審查期間結束。</li></ul><p class="note">依 2026-09-21 可見的 SPM Probable Infrastructure 頁整理；本導覽不建立請求，也不複製帳號內公司、請求人或候選資產。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="third-party-assets"><strong>第三方資產</strong><small>Third Party Assets · 釐清外部服務資產。</small></button><button class="feature-card" data-page="infrastructure"><strong>基礎設施</strong><small>Infrastructure · 核對正式歸屬結果。</small></button></div></article>`;
}

function thirdPartyAssetsPage() {
  return `<article class="doc"><button class="back-link" data-page="probable">← 返回可能相關的基礎設施</button><div class="eyebrow">攻擊面 Attack Surface / Third Party Assets</div><h1>第三方資產</h1><p class="lead">Third Party Assets 集中管理由外部服務商代管、但需要組織監看的資產。它用來區分監控責任與資產所有權；第三方關聯不代表組織擁有或能直接修復該資產。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Attack Surface → Third Party Assets</code>。Upload Assets 會把資產加入監控範圍，Unmonitor 會停止監控選定項目；兩者都應先核對契約、責任與授權。</div><h2>表格欄位</h2>${docTable(['英文','建議中文','用途與判讀'],[['Asset','資產','第三方資產的網域、主機或其他識別值。'],['Asset Type','資產類型','區分網域、IP 或平台支援的其他類型。'],['Company','公司','此資產在目前監控脈絡中所屬的公司。'],['Importance','重要性','標示資產的業務重要程度，用於協助排序。'],['Guest Network Exclusion','訪客網路排除','顯示是否套用訪客網路排除。'],['Guest Network Exclusion End Date','訪客網路排除結束日','排除設定的預計結束日期。'],['Country','國家／地區','外部資料判定的資產地理位置。'],['Identified Products','已辨識產品','外部觀測到的產品或技術線索。'],['Cloud Platform','雲端平台','辨識到的公有雲平台。'],['Cloud Services','雲端服務','與資產相關的雲端服務類型。'],['Cloud Region','雲端區域','資產所在或被辨識的雲端區域。'],['Material/Severe Findings','重大／嚴重發現','高影響發現的數量。'],['Findings','發現事項','與資產相關的全部發現數量。']])}<h2>篩選器</h2>${docTable(['英文','建議中文','何時使用'],[['Asset Type','資產類型','限定特定資產種類。'],['Number of Findings','發現數量','找發現數量較多或特定區間的資產。'],['Importance','重要性','聚焦關鍵或高重要性資產。'],['Grace Period / Grace Period End Date','寬限期／結束日','檢查新納管資產的寬限狀態。'],['Guest Network Exclusion / End Date','訪客網路排除／結束日','找套用排除與即將到期的資產。'],['Cloud Platform / Services / Region','雲端平台／服務／區域','依雲端環境切分資產。'],['Product Support','產品支援狀態','找可能使用停止支援產品的資產。'],['Identified Products','已辨識產品','搜尋特定產品或技術。'],['Vulnerability / Severity','弱點／嚴重度','依 CVE 或弱點嚴重程度篩選。'],['Vulnerability Evidence Certainty / Detection','弱點證據確信度／偵測方式','按證據強度與偵測類型縮小結果。'],['Vulnerability Statement / Visibility','弱點聲明／可見性','依組織聲明與分享範圍篩選。']])}<h2>工具列與操作</h2>${docTable(['介面文字','建議中文','功能／注意'],[['Upload Assets','上傳資產','批次加入第三方資產；先確認格式、歸屬和監控授權。'],['Views / Create View','檢視／建立檢視','載入或保存常用篩選設定。'],['Unmonitor (n)','停止監控（n 筆）','停止監控選定資產；會改變資料範圍，操作前須核准。'],['Search','搜尋','在目前清單中尋找資產。'],['Download as CSV','下載 CSV','匯出目前清單；零筆或無權限時可能停用。'],['Enter full screen','進入全螢幕','放大表格閱讀區域。'],['0 Rows','0 列','目前範圍沒有結果；先檢查篩選與是否已上傳資產，不能直接解讀成沒有第三方風險。']])}<h2>建議操作流程</h2><ol><li>先建立第三方資產納管準則，確認服務商、契約、資產識別值及內外部責任人。</li><li>使用 Upload Assets 前清理重複與錯誤資料，並確認不把自有資產誤列為第三方。</li><li>以 Importance、Material/Severe Findings、產品支援與弱點證據篩選優先項目。</li><li>把外部發現交由合約指定窗口查證，保留供應商回覆、緩解措施與驗證日期。</li><li>只有在服務結束、資產誤列或正式移轉責任後，才使用 Unmonitor，並留下核准紀錄。</li></ol><div class="example"><strong>使用情境：託管網站風險</strong><p>公司網站由服務商代管時，可將網站資產列入第三方監控；發現高風險產品或 CVE 後，先核對契約責任，再由服務商提供修補證據。監控關聯不會把資產所有權轉給公司。</p></div><h2>容易誤判的地方</h2><ul><li><strong>第三方資產不等於自有資產：</strong>要分清所有權、營運權與監控責任。</li><li><strong>0 Rows 不等於零第三方風險：</strong>可能尚未上傳、被篩選或缺少權限。</li><li><strong>產品辨識不是完整清單：</strong>外部觀測需由服務商或內部負責人確認。</li><li><strong>Unmonitor 不會消除風險：</strong>它只停止平台監控，不能取代合約終止或修復。</li><li><strong>地區與雲端資訊可能是託管位置：</strong>不一定等於資料法域或供應商總部。</li></ul><p class="note">依 2026-09-21 可見的 SPM Third Party Assets 頁整理；本導覽不會上傳、停止監控或複製任何帳號資產。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="risk-remediation"><strong>風險改善</strong><small>Risk Remediation · 進入下一個大單元。</small></button><button class="feature-card" data-page="surface-analytics"><strong>攻擊面分析</strong><small>Attack Surface Analytics · 回看風險分布。</small></button></div></article>`;
}

function riskRemediationPage() {
  return `<article class="doc"><button class="back-link" data-page="third-party-assets">← 返回第三方資產</button><div class="eyebrow">改善計畫 Action Plans / Risk Remediation</div><h1>風險改善</h1><p class="lead">Risk Remediation Plan（RRP）依目前會影響等級的發現，為各風險面向計算提升至 A 的高效率改善路徑。它是排序工具，不是修復保證，也不應取代資產重要性與內部風險判斷。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Action Plans → Risk Remediation</code>。頁首目前公司的選擇會影響整份計畫；Generate Forecast、Rerun Plan 與 Refresh Rate 會建立或更新分析，操作前先確認公司與資料日期。</div><h2>計畫卡片與名詞</h2>${docTable(['英文','建議中文','功能與判讀'],[['Risk Remediation Plan (RRP)','風險改善計畫','依計算當下的等級影響發現，排序可能提升風險面向等級的改善項目。'],['Base Plan','基準計畫','目前風險面向的改善基準與各等級所需發現數。'],['Makes up … of Rating','占評等比重','顯示該風險面向在評等中的相對權重；不等於事故發生率。'],['F / D / C / B / A','風險面向等級','顯示目前等級與達到不同目標等級的路徑。'],['Finding(s)','發現事項','該等級階段預計需要處理的發現數量。'],['Total Findings','發現總數','目前計畫範圍內的總發現數。'],['Remediated','已改善','計畫中被判定已處理的發現；仍需核對最新觀測。'],['Report last updated','報告最後更新','計畫資料最近計算時間。'],['Viewing Plan','目前檢視的計畫','顯示此卡片使用的風險面向／計畫版本。'],['Critical Vulnerability Management','重大弱點管理','針對關鍵弱點與修補節奏的風險面向。'],['SSL Configurations','SSL 設定','針對 SSL／TLS 設定問題的風險面向。'],['SSL Certificates','SSL 憑證','針對憑證有效性及設定問題的風險面向。'],['Web Application Security','Web 應用程式安全','針對可從外部觀測的網站應用安全問題。'],['Desktop Software / Mobile Software','桌面軟體／行動軟體','針對軟體版本與支援狀態的風險面向。'],['DMARC','DMARC 郵件驗證','針對網域郵件驗證政策的風險面向。']])}<h2>操作控制</h2>${docTable(['介面文字','建議中文','功能／注意'],[['Generate Forecast','產生預測','以前述計畫資料建立評等預測；結果為模擬，不是承諾。'],['Forecasting','評等預測','前往跨風險面向的模擬頁。'],['Risk Vector selector','風險面向選擇器','切換或選擇卡片所用的計畫。'],['Refresh Rate','更新頻率','設定計畫自動更新節奏；Off 表示未啟用自動更新。'],['Rerun Plan','重新執行計畫','以目前資料重新計算；結果可能因發現及評等資料更新而改變。'],['View Plan','查看計畫','開啟該風險面向的發現清單及改善順序。'],['Learn more','閱讀更多','查看 RRP 官方說明與最新計算規則。']])}<h2>建議操作流程</h2><ol><li>確認頁首公司、目前評等與 Report last updated，避免使用過期計畫。</li><li>比較各風險面向的目前等級、評等比重與達到下一級所需處理的發現數。</li><li>用 View Plan 打開具體項目，核對資產、證據、嚴重度、觀測時間及修復可行性。</li><li>把計畫效率與資產重要性、實際可利用性、法規及業務影響一起排序。</li><li>完成修補後驗證外部訊號，再依需要 Rerun Plan；用 Forecasting 評估跨面向情境，但不要承諾預測分數。</li></ol><div class="example"><strong>使用情境：選擇改善投資</strong><p>某面向只需處理少量發現即可提升一級，不代表它必然比重大弱點更優先。應先確認發現落在哪些資產、是否可利用及業務影響，再決定快速改善與高風險修補如何並行。</p></div><h2>容易誤判的地方</h2><ul><li><strong>提升等級不等於消除風險：</strong>RRP 以評等影響效率排序，未涵蓋所有內部風險。</li><li><strong>Finding 數不能跨面向直接比較：</strong>每個面向的計算方式與證據不同。</li><li><strong>Remediated 不一定立即反映在評等：</strong>仍受重新觀測、資料更新與計算時程影響。</li><li><strong>權重不是風險機率：</strong>Makes up … of Rating 只描述評等構成。</li><li><strong>重新執行會改變結果：</strong>比較前應保留計算日期、範圍與假設。</li></ul><p class="note">依 2026-09-21 可見的 SPM Risk Remediation Plan 頁整理；本導覽不複製帳號中的評等、發現數或計畫識別值。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="forecasting"><strong>評等預測</strong><small>Forecasting · 模擬跨面向改善。</small></button><button class="feature-card" data-page="findings-table"><strong>發現事項表格</strong><small>Findings Table · 核對改善證據。</small></button></div></article>`;
}

function forecastingPage() {
  return `<article class="doc"><button class="back-link" data-page="risk-remediation">← 返回風險改善</button><div class="eyebrow">改善計畫 Action Plans / Forecasting</div><h1>評等預測</h1><p class="lead">Forecasting 用情境項目與預計完成日期，模擬評等可能的變化，並可在啟用監控後比較實際評等與預測。它適合規劃和溝通，不是對未來分數的保證。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Action Plans → Forecasting</code>。清單可能包含自己的預測與他人分享的預測；建立、刪除或分享前先核對公司、權限與使用目的。</div><h2>預測卡片欄位</h2>${docTable(['英文','建議中文','功能與判讀'],[['Forecasting','評等預測','預測清單與篩選頁。'],['New Forecast','新增預測','建立新的公司評等情境。'],['Forecast name','預測名稱','用來識別情境；應採有意義且不含敏感資訊的名稱。'],['Company','公司','此預測所屬的公司；不同公司不可直接混用。'],['Start Date','開始日期','情境預測開始計算或監看的日期。'],['Rating Evolution','評等變化','顯示起始評等與預測目標／結果的變化方向。'],['Scenario Items','情境項目','納入模擬的風險面向或改善項目。'],['Due on','預計完成日','各情境項目的假設完成日期，不是系統自動建立的 SLA。'],['Last saved on','最後儲存時間','預測最近一次保存的時間。'],['View Forecast','查看預測','開啟情境明細、趨勢與監控資訊。'],['Delete','刪除','永久移除預測；屬破壞性操作，需先確認擁有者及保存需求。'],['No Forecast Scenario defined','未定義預測情境','預測存在，但沒有設定情境項目。']])}<h2>狀態與分享篩選</h2>${docTable(['英文','建議中文','判讀'],[['Inactive','未啟用','情境尚未開始監控；卡片可能顯示 No monitoring yet。'],['Active','進行中','正在依開始日期與情境追蹤實際變化。'],['Finished','已結束','預測監控期間已完成；不代表所有改善工作均完成。'],['My Forecasts','我的預測','由目前使用者建立或擁有的預測。'],['Shared with me','與我分享','其他使用者分享給目前帳號的預測。'],['No monitoring yet','尚未監控','目前沒有實際監控資料，不能用來判定情境是否達成。'],['Rating lower than forecasted','評等低於預測','實際評等低於情境預期；應查找資料、事件或假設差異。']])}<h2>建議操作流程</h2><ol><li>先確認要模擬的公司、目前評等、基準日期與規劃期間。</li><li>以 New Forecast 建立清楚命名的情境，加入風險面向及合理的 Due on 日期。</li><li>記錄假設：預計處理哪些發現、資產範圍、資料更新延遲和其他同時變動因素。</li><li>啟用後定期比較 Rating Evolution 與實際狀況；若偏離預測，回到發現事項和評等變化查原因。</li><li>分享時確認對象與資料敏感性；預測不再需要時，先保存必要紀錄再刪除。</li></ol><div class="example"><strong>使用情境：季度改善規劃</strong><p>將 SSL 設定與開放連接埠改善分別設定預計完成日，模擬評等路徑。向主管報告時要同時列出假設與不確定性，不能把模擬終點當成承諾分數。</p></div><h2>容易誤判的地方</h2><ul><li><strong>預測不是保證：</strong>實際評等仍受新發現、資產變化、演算法與觀測時間影響。</li><li><strong>Due on 不是自動 SLA：</strong>它是情境假設日期，仍需內部工作流程追蹤。</li><li><strong>Finished 不等於全部修復：</strong>只表示預測監控階段結束。</li><li><strong>評等上升不等於所有風險降低：</strong>情境可能只包含部分風險面向。</li><li><strong>刪除不可作為結案：</strong>需要依治理規範保留假設、結果及決策紀錄。</li></ul><p class="note">依 2026-09-21 可見的 SPM Forecasting 清單頁整理；本導覽不複製帳號內的預測名稱、公司、分數或日期。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="subsidiary-improvement"><strong>子公司改善</strong><small>Subsidiary Improvement · 跨組織安排改善。</small></button><button class="feature-card" data-page="risk-remediation"><strong>風險改善</strong><small>Risk Remediation · 回到具體改善路徑。</small></button></div></article>`;
}

function subsidiaryImprovementPage() {
  return `<article class="doc"><button class="back-link" data-page="forecasting">← 返回評等預測</button><div class="eyebrow">改善計畫 Action Plans / Subsidiary Improvement</div><h1>子公司改善</h1><p class="lead">Subsidiary Improvement 以 Impact Analysis 排出逐步改善子公司／組織節點後，母公司評等可能上升的路徑。它協助跨組織排序，但圖表是影響模擬，不代表子公司已完成修復。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Action Plans → Subsidiary Improvement</code>。分析以 Ratings Tree 的組織結構和目前資料為基礎；先核對母公司、子公司範圍與 Last Updated。</div><h2>圖表與欄位</h2>${docTable(['英文','建議中文','功能與判讀'],[['Impact Analysis','影響分析','模擬改善不同子公司／節點後對母公司評等的可能影響。'],['Last Updated','最後更新','分析最近計算的日期；跨期比較時必須記錄。'],['Export (.csv)','匯出 CSV','下載目前分析資料；注意公司評等與組織資訊敏感性。'],['Step','步驟','建議改善序列中的階段。'],['Current Rating','目前評等','分析起點的母公司評等。'],['Projected Rating','預測評等','依模擬步驟可能達到的評等，不是保證。'],['Rating Improvements','評等改善','圖表橫軸，顯示各步驟可能帶來的累積評等變化。'],['Subsidiary / organization node','子公司／組織節點','圖中每一步對應的改善對象。'],['Basic (300–630)','基礎（300–630）','介面上的評等層級區間。'],['Intermediate (640–730)','中階（640–730）','介面上的評等層級區間。'],['Advanced (740–820)','進階（740–820）','介面上的評等層級區間。'],['Learn more','閱讀更多','查看子公司改善計算與限制的官方說明。']])}<h2>重要限制</h2>${docTable(['原介面提示','建議解讀'],[['Critical Vulnerability Management can only be calculated on the parent level','重大弱點管理風險面向只能在母公司層級計算，不能按子公司計算。'],['No value','無數值','該步驟或節點目前沒有可顯示的改善值；不能自行當作零影響。'],['Ratings Tree scope','評等樹範圍','子公司、測試節點或其他組織單位的結構會影響分析對象。'],['Projected Rating','預測評等','只反映模型假設下的結果，實際分數還會受新發現、資產和資料更新影響。']])}<h2>建議操作流程</h2><ol><li>確認母公司與 Ratings Tree 中的子公司／組織節點是否正確，並記錄 Last Updated。</li><li>閱讀 Current Rating、Projected Rating 與每個 Step，找出可能對母公司評等影響較大的節點。</li><li>進入該子公司的風險面向與發現事項，核對具體資產、證據、嚴重度和實際改善成本。</li><li>與子公司負責人協調工作、期限和驗證方式；不能只因預測增分高就忽略業務風險。</li><li>定期重新查看分析並匯出一致日期的資料，追蹤組織結構與實際評等變化。</li></ol><div class="example"><strong>使用情境：跨子公司安排改善</strong><p>圖表顯示某子公司是早期改善步驟時，先確認它是否真的屬於評等樹中的有效節點，再查看其高影響發現。若另一子公司有重大業務風險，即使預測增分較低，也可能需要優先處理。</p></div><h2>容易誤判的地方</h2><ul><li><strong>步驟不是強制修復順序：</strong>還要考慮資產重要性、利用可能性、成本與法規。</li><li><strong>預測評等不是承諾：</strong>模型結果可能隨資料和組織結構改變。</li><li><strong>節點名稱不一定是法律實體：</strong>可能包含測試、區域或自訂組織節點。</li><li><strong>No value 不等於零風險：</strong>只表示目前分析沒有可呈現的數值。</li><li><strong>重大弱點管理有母公司限制：</strong>不能把該面向的母公司計算拆解成子公司分數。</li></ul><p class="note">依 2026-09-21 可見的 SPM Subsidiary Improvement 頁整理；本導覽不複製帳號內公司名稱、評等或步驟資料。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="control-insights"><strong>控制措施洞察</strong><small>Control Insights · 對照安全控制。</small></button><button class="feature-card" data-page="ratings-tree"><strong>評等樹</strong><small>Ratings Tree · 核對組織結構。</small></button></div></article>`;
}

function controlInsightsPage() {
  return `<article class="doc"><button class="back-link" data-page="subsidiary-improvement">← 返回子公司改善</button><div class="eyebrow">改善計畫 Action Plans / Control Insights</div><h1>控制措施洞察</h1><p class="lead">Control Insights 使用 BitSight 已蒐集的外部可觀測資料，推論安全控制看起來是否有效，並映射到 CIS Critical Security Controls。它能指出控制缺口，但不是內部控制稽核或合規認證。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Action Plans → Control Insights</code>。此功能依 SPM 方案提供；資料每月以最近一個完整月份重新評估，預設可查看六個月歷史。</div><h2>框架與頁面名詞</h2>${docTable(['英文','建議中文','功能與判讀'],[['Framework','控制框架','切換目前用來對照洞察的框架。'],['CIS v8 (CIS 18)','CIS 控制措施 v8','目前支援的最新 CIS Critical Security Controls 版本。'],['CIS v7.1 (CIS 20)','CIS 控制措施 v7.1','前一版 CIS 控制框架。'],['Controls','控制措施','查看各控制的評估與形成判斷的洞察。'],['Safeguards (v8)','防護措施（v8）','CIS v8 控制下更細的實作項目。'],['Sub-Controls (v7.1)','子控制（v7.1）','CIS v7.1 控制下的細項。'],['Implementation Groups','實作群組','CIS 的 IG1、IG2、IG3 分組；較低群組不一定需要實作所有 IG3 項目。'],['Insights','洞察','由外部觀測推論出的正向或負向控制訊號，與特定框架無關後再映射。'],['Observations','觀測資料','產生洞察的外部遙測證據。'],['Insight Assessment','洞察評估','Positive 表示控制看起來有效；Negative 表示看起來無效。'],['Control Evaluation','控制評估','綜合當月映射洞察判定整體控制狀態。'],['User-Submitted Evaluation & Comments','使用者提交的評估與留言','補充內部觀點；以控制為單位，對組織私有並持續保留直到刪除。']])}<h2>控制狀態</h2>${docTable(['英文','建議中文','判定方式'],[['Acceptable','可接受','當月至少一個正向洞察，且沒有負向洞察。'],['Needs Improvement','需要改善','當月至少有一個負向洞察，顯示控制可能未有效運作。'],['Not Enough Data','資料不足','當月沒有正向或負向洞察，無足夠資料形成相關判斷。'],['Positive Insight','正向洞察','外部訊號顯示某控制或最佳實務可能有效。'],['Negative Insight','負向洞察','外部訊號顯示某控制或最佳實務可能無效。']])}<h2>資料特性與限制</h2>${docTable(['項目','說明'],[['Monthly evaluation','每月使用前一個完整月份的資料評估控制表現。'],['Six-month history','預設提供六個月歷史，用於觀察表現一致性。'],['Parallel to ratings','使用與評等相同的底層觀測，但以控制與績效角度另行解讀。'],['No direct rating impact','Control Insights 不直接影響 BitSight Security Rating。'],['Private organization view','控制洞察目前只供自己的組織查看；使用者評估與留言也不向第三方顯示。'],['Framework mapping','同一洞察可映射到多個框架控制；映射是脈絡化，不是完整內部稽核。'],['Executive Summary report','控制措施洞察主管摘要報表','可將目前評估與歷史整理給利害關係人。']])}<h2>建議操作流程</h2><ol><li>確認頁首公司、資料月份和 Framework，避免跨公司或跨框架混用結果。</li><li>先看 Needs Improvement，再打開控制及其 Negative／Positive Insights，追到原始 Observations。</li><li>將外部觀測與內部政策、設定、日誌、測試和稽核證據交叉驗證。</li><li>需要補充背景時提交內部評估與留言，清楚標示證據、日期、負責人及例外條件。</li><li>用六個月歷史觀察一致性；對主管分享時區分平台推論、內部結論與待改善工作。</li></ol><div class="example"><strong>使用情境：控制顯示需要改善</strong><p>若某 CIS 控制因暴露管理介面而出現負向洞察，先查看觀測來源與受影響資產，再確認是否有身分驗證、網路限制或補償控制。內部控制有效性不能只由外部訊號下結論。</p></div><h2>容易誤判的地方</h2><ul><li><strong>Acceptable 不是通過稽核：</strong>只代表當月外部證據沒有負向洞察且至少有一項正向洞察。</li><li><strong>Not Enough Data 不是安全：</strong>它表示缺少可形成判斷的外部資料。</li><li><strong>Needs Improvement 不是已證實控制失效：</strong>仍需內部證據查證。</li><li><strong>不直接影響評等：</strong>Control Insights 與評等共用觀測，但走不同的解讀流程。</li><li><strong>使用者留言是補充脈絡：</strong>不能用主觀說明取代技術修復與驗證。</li></ul><p class="note">依 2026-09-21 的 SPM 導覽入口與 BitSight 官方 Control Insights 知識庫核對；原帳號頁面當時停在載入骨架，因此未臆測未顯示的按鈕或卡片。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="peer-analytics"><strong>同業分析</strong><small>Peer Analytics · 進入下一個大單元。</small></button><button class="feature-card" data-page="risk-remediation"><strong>風險改善</strong><small>Risk Remediation · 將洞察轉成改善計畫。</small></button></div></article>`;
}

function peerAnalyticsPage() {
  return `<article class="doc"><button class="back-link" data-page="control-insights">← 返回控制措施洞察</button><div class="eyebrow">同業比較 Peer Comparison / Peer Analytics</div><h1>同業分析</h1><p class="lead">Peer Analytics 把目前公司與自訂同業群組比較，呈現評等分布、風險面向差距，以及同業常見的感染、開放連接埠、弱點和停止支援軟體。比較結果取決於群組成員，不能當作絕對安全標準。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Peer Comparison → Peer Analytics</code>。先確認 Peer Group 和目前公司；Edit Peer Group 會改變比較基準，更新前應記錄群組目的與成員。</div><h2>總覽指標與圖表</h2>${docTable(['英文','建議中文','功能與判讀'],[['Peer Group','同業群組','目前用來比較的一組公司。'],['Edit Peer Group','編輯同業群組','調整比較成員；會影響所有中位數、百分位與常見項目。'],['Bottom 1% / Bottom 25%','後 1%／後 25%','目前公司在群組中的較低相對位置。'],['Median','中位數','同業群組評等的中間位置。'],['Top 25%','前 25%','群組中較高評等四分位的參考值。'],['… points more than company','比目前公司高 … 分','比較基準與目前評等的差距。'],['Peer Group Distribution over Rating Ranges','同業群組評等區間分布','查看各評等區間占群組的比例。'],['Risk Vector Performance','風險面向表現','彙整 Worse than、In Line with、Better than Peer Group 的面向數量。'],['Risk Vectors Worse Than Peer Group','低於同業群組的風險面向','比較公司、群組中位數與前 25% 的面向等級。'],['Risk Vectors Better Than Peer Group','優於同業群組的風險面向','查看相對表現較好的面向。'],['View Risk Position','查看風險相對位置','前往完整面向比較頁。'],['Reports','報表','從目前比較脈絡產出或前往相關報表；載入未完成時可能停用。']])}<h2>同業常見風險表格</h2>${docTable(['英文','建議中文','用途'],[['Top Infections in Peer Group','同業群組常見感染','列出感染類型及群組受影響比例。'],['Top Open Ports in Peer Group','同業群組常見開放連接埠','列出服務／連接埠問題及群組受影響比例。'],['Top Vulnerabilities in Peer Group','同業群組常見弱點','列出 CVE 及群組受影響比例。'],['Top Unsupported Software in Peer Group','同業群組常見停止支援軟體','列出產品及群組受影響比例。'],['% Affected in Peer Group','同業群組受影響比例','有該項訊號的群組公司占比，不是事件發生率。'],['Affects Company','是否影響目前公司','指出目前公司是否也有該項外部訊號。'],['Show only those affecting company','僅顯示影響目前公司的項目','切換後只看同業常見且目前公司也受影響的項目。']])}<h2>建議操作流程</h2><ol><li>確認目前公司與 Peer Group，檢查成員是否在產業、規模、地區及業務模式上具有可比性。</li><li>查看評等分布、Median 和 Top 25%，了解目前公司相對位置，而不是只看單一排名。</li><li>用 Risk Vector Performance 找出低於同業的面向，再進入 View Risk Position 檢查細節。</li><li>在四類常見風險表格開啟「僅顯示影響目前公司」，找出同業普遍且自身也存在的問題。</li><li>回到發現事項與資產明細驗證，依自身業務風險設定改善目標。</li></ol><div class="example"><strong>使用情境：設定同業改善基準</strong><p>公司低於群組中位數時，先確認群組是否合理，再找出差距最大的風險面向。若同業普遍存在某弱點，也不能把它視為可接受；同業資料是排序參考，不是風險豁免。</p></div><h2>容易誤判的地方</h2><ul><li><strong>相對較好不等於安全：</strong>整個群組可能同時存在相同弱點。</li><li><strong>群組成員決定結果：</strong>編輯群組後，百分位與中位數都會改變。</li><li><strong>受影響比例不是事故機率：</strong>只表示群組中有此觀測訊號的公司比例。</li><li><strong>排名差距不等於改善成本：</strong>仍需查看資產、證據和控制環境。</li><li><strong>小群組的百分位波動較大：</strong>分享結果時應附上群組定義和資料日期。</li></ul><p class="note">依 2026-09-21 可見的 SPM Peer Analytics 頁整理；本導覽不複製帳號內群組成員、評等、感染或弱點清單。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="risk-position"><strong>風險相對位置</strong><small>Risk Position · 比較每個風險面向。</small></button><button class="feature-card" data-page="risk-vectors"><strong>風險面向</strong><small>Risk Vectors · 回到自身面向證據。</small></button></div></article>`;
}

function riskPositionPage() {
  return `<article class="doc"><button class="back-link" data-page="peer-analytics">← 返回同業分析</button><div class="eyebrow">同業比較 Peer Comparison / Risk Position</div><h1>風險相對位置</h1><p class="lead">Risk Position 將「與同業群組的差距」和「對評等的影響」放進矩陣，產生 Critical、High、Medium、Low 優先度，再以清單比較公司、中位數與前 25% 的風險面向等級。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Peer Comparison → Risk Position</code>。所有差距和優先度都以目前 Peer Group 為基準；群組改變時，結果也會改變。</div><h2>差距分析矩陣</h2>${docTable(['英文','建議中文','功能與判讀'],[['Risk Vector Gap Analysis','風險面向差距分析','把各風險面向依相對差距與評等影響放入矩陣。'],['Priority: Critical / High / Medium / Low','優先度：關鍵／高／中／低','矩陣綜合結果，用於調查排序，不是弱點嚴重度。'],['Risk Vector Impact on Rating','風險面向對評等的影響','矩陣的一個維度，分為 High、Medium、Low。'],['Better than most of Peer Group (Top 25%)','優於大多數同業（前 25%）','公司在該面向位於群組較高區間。'],['In Line with Peer Group','與同業群組相近','公司面向表現與群組基準大致一致。'],['Worse than most of Peer Group (Bottom 25%)','低於大多數同業（後 25%）','公司在該面向位於群組較低區間。'],['Risk vectors in matrix cell','矩陣格內的風險面向','點選或查看同一差距／影響組合的面向。'],['+ n More','另有 n 項','表示該矩陣格還有未直接顯示的面向。']])}<h2>比較清單欄位</h2>${docTable(['英文','建議中文','判讀'],[['Comparison with Peer Group Risk Vectors','與同業群組比較風險面向','逐項列出優先度與等級差距。'],['Priority','優先度','由差距矩陣產生的處理參考。'],['Ranking','排名位置','例如 Bottom 2% 或 Top 1%，受群組成員影響。'],['Company','公司','目前公司的風險面向等級。'],['Median','中位數','同業群組該面向的中位等級。'],['Top 25%','前 25%','群組較高四分位的參考等級。'],['Search','搜尋','在風險面向比較清單中尋找特定名稱。'],['Reports','報表','從比較脈絡前往報表；資料未載入完成時可能停用。']])}<h2>常見面向名稱</h2>${docTable(['英文','建議中文','主要觀察'],[['Critical Vulnerability Management','重大弱點管理','重大弱點的修補節奏與暴露情況。'],['Spam Propagation','垃圾郵件散布','組織網路的垃圾郵件活動訊號。'],['Potentially Exploited','疑似遭利用','可能與弱點利用相關的外部訊號。'],['SSL Configurations / SSL Certificates','SSL 設定／SSL 憑證','TLS／SSL 設定與憑證管理。'],['Botnet Infections / Malware Servers','殭屍網路感染／惡意程式伺服器','疑似受入侵系統相關訊號。'],['Web Application Security / Open Ports','Web 應用程式安全／開放連接埠','網站設定與對外服務暴露。'],['DMARC / SPF / DKIM','DMARC／SPF／DKIM','郵件網域驗證設定。'],['File Sharing / Unsolicited Communications','檔案分享／非請求通訊','P2P 與異常通訊相關活動。'],['Desktop / Mobile / Server Software','桌面／行動／伺服器軟體','外部可見的軟體版本與支援狀態。']])}<h2>建議操作流程</h2><ol><li>確認 Peer Group 成員與目前公司，等待群組資料完整載入。</li><li>先看矩陣中的 Critical／High 格，辨識同業差距大且可能影響評等較高的面向。</li><li>在清單比較 Company、Median、Top 25% 與 Ranking，確認差距大小。</li><li>前往該風險面向和發現事項，核對資產、證據、實際可利用性與改善成本。</li><li>以業務風險校正矩陣排序，建立可追蹤的改善計畫，並保留群組與資料日期。</li></ol><div class="example"><strong>使用情境：挑選優先面向</strong><p>某面向落在 Critical 且排名後段時，可作為優先調查候選；但若證據屬低重要性資產，另一個 High 面向反而涉及核心系統，實際處理順序仍應依業務風險調整。</p></div><h2>容易誤判的地方</h2><ul><li><strong>Priority 不是 Finding Severity：</strong>它是同業差距與評等影響的組合結果。</li><li><strong>Bottom 25% 不等於發生事故：</strong>只表示相對群組位置較低。</li><li><strong>In Line 不等於安全：</strong>同業群組可能普遍存在相同問題。</li><li><strong>高評等影響不必然等於高業務影響：</strong>需用資產與內部風險資料校正。</li><li><strong>群組變更會重算位置：</strong>跨期報告要固定比較群組與日期。</li></ul><p class="note">依 2026-09-21 可見的 SPM Risk Position 頁整理；本導覽不複製帳號內的同業群組、排名或公司等級。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="collaboration"><strong>協作</strong><small>Collaboration · 進入下一個大單元。</small></button><button class="feature-card" data-page="peer-analytics"><strong>同業分析</strong><small>Peer Analytics · 回到群組總覽。</small></button></div></article>`;
}

function collaborationPage() {
  return `<article class="doc"><button class="back-link" data-page="risk-position">← 返回風險相對位置</button><div class="eyebrow">協作與通知 / Collaboration</div><h1>協作</h1><p class="lead">Collaboration Inbox 集中顯示組織間的協作邀請、寄件人、收件人、待審項目與處理狀態。回覆前應確認對方身分、分享範圍及資料敏感性。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Collaboration</code>。清單可能同時包含自己組織與外部公司的邀請；開啟或處理前先核對 From、Sender 與 Recipient(s)。</div><h2>表格欄位</h2>${docTable(['英文','建議中文','功能與判讀'],[['Collaboration Inbox','協作收件匣','查看收到或參與的協作邀請。'],['Invitations','邀請數','目前範圍內的協作邀請筆數；受篩選條件影響。'],['Date','日期','邀請建立或寄送日期。'],['From','來源公司','發起協作的公司或組織。'],['Sender','寄件人','實際發起邀請的使用者或電子郵件。'],['Recipient(s)','收件人','邀請的接收者；+ n more 表示還有其他人。'],['Items for Review','待審項目','對方要求檢視的風險面向或其他項目。'],['Status','狀態','例如 Open 或 Resolved，表示協作流程狀態。'],['Open','未結案','協作仍在等待回覆、審查或後續處理。'],['Resolved','已結案','協作流程已標記完成；不代表相關風險已技術修復。'],['Row actions','列操作','每列末端的可用操作；圖示依權限與狀態而異，執行前先開啟內容確認。']])}<h2>篩選器與工具</h2>${docTable(['英文','建議中文','何時使用'],[['Date','日期','限定邀請期間。'],['From','來源公司','找特定公司的協作。'],['Sender','寄件人','依發起者篩選。'],['To / Recipient(s)','寄送對象／收件人','查找特定接收者。'],['Collaboration Reason','協作原因','依邀請目的分類。'],['Items for Review','待審項目','找涉及特定風險面向的邀請。'],['Status','狀態','區分 Open、Resolved 等流程狀態。'],['Columns','欄位','調整清單顯示欄位。'],['Views / Create View','檢視／建立檢視','載入或保存常用篩選。'],['Search','搜尋','在目前邀請清單中搜尋。'],['Download as CSV','下載 CSV','匯出清單；注意人員、公司與風險資訊敏感性。'],['Enter full screen','進入全螢幕','放大清單閱讀區域。']])}<h2>建議操作流程</h2><ol><li>確認 Filters／Views 和目前邀請筆數，再依 Status 找出 Open 項目。</li><li>核對 From、Sender、Recipient(s) 與 Collaboration Reason，必要時用既有管道驗證對方身分。</li><li>檢查 Items for Review，回到風險面向、發現事項與資產明細確認內容。</li><li>回覆時只分享完成目的所需的最少資料，避免貼入憑證、個資或不必要的內部細節。</li><li>完成回覆與證據確認後再標記 Resolved，並依內部規範保存決策紀錄。</li></ol><div class="example"><strong>使用情境：收到風險面向審查邀請</strong><p>先驗證邀請公司與寄件人，再檢查對方要求的 SSL 或弱點項目。若要提供修復證據，應先確認收件人與可分享範圍，必要時只提供摘要而非完整內部報告。</p></div><h2>容易誤判的地方</h2><ul><li><strong>邀請不代表可信：</strong>仍需核對身分、公司關係及協作目的。</li><li><strong>Open 不等於尚未讀取：</strong>可能已開始處理但尚未結案。</li><li><strong>Resolved 不等於風險消失：</strong>它是協作流程狀態，不是技術驗證結果。</li><li><strong>Items for Review 可能是摘要：</strong>應回到原始證據確認。</li><li><strong>匯出資料需控管：</strong>CSV 可能包含公司、人員及安全資訊。</li></ul><p class="note">依 2026-09-21 可見的 SPM Collaboration Inbox 頁整理；本導覽不複製帳號內公司、人員、信箱或邀請內容。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="configured-alerts"><strong>已設定警示</strong><small>Configured Alerts · 管理通知規則。</small></button><button class="feature-card" data-page="alert-logs"><strong>警示紀錄</strong><small>Alerts Logs · 查核觸發歷程。</small></button></div></article>`;
}

function configuredAlertsPage() {
  return `<article class="doc"><button class="back-link" data-page="collaboration">← 返回協作</button><div class="eyebrow">協作與通知 / Alerts / Configured Alerts</div><h1>已設定警示</h1><p class="lead">Configured Alerts 管理警示規則、監控範圍、收件人與訂閱狀態。警示能縮短發現變化的時間，但規則未涵蓋的事件不會因此自動被偵測或通知。</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>Alerts → Configured Alerts</code>。Add Alert、Subscribe、Unsubscribe 與 Delete 都會改變通知行為；操作前確認擁有者、公司範圍及收件人。</div><h2>清單欄位與操作</h2>${docTable(['英文','建議中文','功能與注意'],[['Add Alert','新增警示','啟動五步驟精靈建立規則。'],['Name','名稱','警示規則名稱，應清楚指出用途與範圍。'],['Alert Type','警示類型','規則監看的事件種類。'],['Owner','擁有者','建立或管理規則的帳號。'],['Subsidiaries/Benchmark Groups','子公司／基準群組','規則套用的公司或比較群組範圍。'],['Recipients','收件人','接收通知的人員或地址。'],['Status','狀態','規則目前是否啟用或可用。'],['Actions','操作','單一規則可用的編輯或管理操作。'],['Show Shared Alerts','顯示共享警示','切換是否顯示他人分享的規則。'],['Subscribe','訂閱','讓選定規則開始寄送給目前使用者或依設定訂閱。'],['Unsubscribe','取消訂閱','停止接收選定規則通知；不會刪除規則。'],['Delete','刪除','刪除選定規則；屬破壞性操作。'],['Search','搜尋','依目前清單尋找警示。'],['0 Alerts','0 個警示','目前範圍沒有規則；也可能與共享切換或權限相關。']])}<h2>新增警示的五個步驟</h2>${docTable(['步驟','建議中文','用途'],[['1. Alert Type','警示類型','選擇要監控的變化。'],['2. Options','選項','設定該警示類型的條件或門檻。'],['3. Subsidiaries','子公司','選擇規則涵蓋的公司／子公司。'],['4. Recipients','收件人','設定通知對象。'],['5. Confirm','確認','檢查全部設定後建立規則。']])}<h2>警示類型</h2>${docTable(['英文','建議中文','通知條件'],[['New Findings','新增發現','出現符合指定條件的新發現時通知。'],['New Infrastructure Changes','新增基礎設施變更','攻擊面新增／移除 CIDR、IP 或網域時通知。'],['Vulnerabilities & Infections','弱點與感染','偵測到特定風險面向的弱點或 Compromised Systems 感染時通知。'],['Risk Vector Grades','風險面向等級','指定風險面向等級改變時通知。'],['Bitsight Rating','BitSight 評等','資安評等改變達指定分數門檻時通知。'],['Exposed Credentials','外洩憑證','BitSight 發現組織新的外洩憑證時通知。'],['Public Disclosures','公開揭露','偵測到新的公開揭露、資料外洩或資安事件時通知。'],['Daily Ratings Change report','每日評等變化報表','用於理解每日評等改變的底層原因，可執行或排程。']])}<h2>建議操作流程</h2><ol><li>先盤點現有規則、Owner、Status、範圍與 Recipients，避免重複通知。</li><li>新增時選擇 Alert Type，再設定足以捕捉重要變化、又不造成大量噪音的條件。</li><li>限定正確子公司／群組，收件人使用角色信箱或明確的值班責任人。</li><li>在 Confirm 再次檢查名稱、條件、範圍與收件人；建立後用 Alerts Logs 驗證實際觸發。</li><li>定期清理離職人員、失效群組與重複規則；刪除前確認沒有其他人依賴該規則。</li></ol><div class="example"><strong>使用情境：監控重大新發現</strong><p>建立 New Findings 規則時，只涵蓋重要子公司與高影響條件，並寄給可採取行動的團隊。若通知量過高，應調整條件而不是直接取消所有警示。</p></div><h2>容易誤判的地方</h2><ul><li><strong>未收到警示不等於沒有風險：</strong>可能因條件、範圍、資料延遲或寄送問題未觸發。</li><li><strong>取消訂閱不同於刪除：</strong>前者停止接收，後者移除規則。</li><li><strong>共享規則仍要核對範圍：</strong>不能假設他人的條件符合自己的責任。</li><li><strong>評等變化不是單一事件：</strong>需要 Daily Ratings Change 或明細查原因。</li><li><strong>收件人越多不一定越有效：</strong>應有明確分流與處理責任。</li></ul><p class="note">依 2026-09-21 可見的 SPM Configured Alerts 與 Add Alert 精靈整理；本導覽不建立、刪除或修改任何帳號警示。</p><h2>接著閱讀</h2><div class="feature-grid"><button class="feature-card" data-page="alert-logs"><strong>警示紀錄</strong><small>Alerts Logs · 驗證實際觸發。</small></button><button class="feature-card" data-page="infections"><strong>感染事件</strong><small>Infections · 查看感染通知。</small></button></div></article>`;
}

function topicPage(p) {
  const [path,focus,usage,caution] = details[p.id];
  const siblings = groups.find(([name]) => name===p.group)[1].filter(([id]) => id!==p.id).slice(0,4);
  return `<article class="doc"><button class="back-link" data-page="home">← 返回學習索引</button><div class="eyebrow">${esc(p.group)} / ${esc(p.en)}</div><h1>${esc(p.zh)}</h1><p class="lead">${esc(p.summary)}</p><div class="callout"><strong>進入路徑</strong><br>SPM 側欄 <code>${esc(path)}</code>。若頁面涉及特定公司，請先核對頂端目前選取的公司；可見項目依權限與授權而異。</div><h2>這頁用來做什麼</h2><p>${esc(focus)}。${esc(usage)}</p><h2>英文與中文對照</h2><div class="doc-table"><table><thead><tr><th>原介面文字</th><th>建議中文</th><th>用途</th></tr></thead><tbody><tr><td><strong>${esc(p.en)}</strong></td><td>${esc(p.zh)}</td><td>${esc(p.summary)}</td></tr><tr><td><strong>${esc(p.group.split(' ').slice(1).join(' ') || 'SPM')}</strong></td><td>${esc(p.group.split(' ')[0])}</td><td>原介面側欄的所屬範圍。</td></tr></tbody></table></div><h2>建議操作流程</h2><ol><li>從左側選單進入 <strong>${esc(p.en)}</strong>，確認頁首公司、範圍及資料期間。</li><li>${esc(usage)}</li><li>需要採取行動前，回到原始發現、資產或其他佐證資料核對。</li></ol><div class="example"><strong>使用情境</strong><p>當需要「${esc(p.summary)}」時，先以此頁建立線索，再依問題往相關明細頁深入調查。</p></div><h2>注意事項</h2><ul><li>${esc(caution)}</li><li>本頁提供介面名稱與判讀方向；實際按鈕、篩選條件及資料以目前原系統為準。</li></ul><p class="note">依 2026-09-18 可見的 SPM 側欄名稱整理；中文為教學譯名，非官方譯文。細部欄位尚待逐頁核對，不推定未驗證的控制項。</p>${siblings.length ? `<h2>同一選單的其他頁面</h2><div class="feature-grid">${siblings.map(([id,zh,en]) => `<button class="feature-card" data-page="${id}"><strong>${esc(zh)}</strong><small>${esc(en)}</small></button>`).join('')}</div>` : ''}</article>`;
}

function render() {
  const id = decodeURIComponent(location.hash.slice(1)) || 'home';
  const page = pages[id] || pages.home;
  const specialized = {'home':homePage,'dashboard':dashboardPage,'company-details':companyDetailsPage,'risk-vectors':riskVectorsPage,'ratings-tree':ratingsTreePage,'company-list':companyListPage,'subsidiaries':subsidiariesPage,'assessments':assessmentsPage,'breach':breachPage,'badge':badgePage,'findings-table':findingsTablePage,'issue-tracking':issueTrackingPage,'vulnerability':vulnerabilityPage,'infrastructure':infrastructurePage,'surface-analytics':surfaceAnalyticsPage,'work-from-home':workFromHomePage,'cloud-sync':cloudSyncPage,'probable':probablePage,'third-party-assets':thirdPartyAssetsPage,'risk-remediation':riskRemediationPage,'forecasting':forecastingPage,'subsidiary-improvement':subsidiaryImprovementPage,'control-insights':controlInsightsPage,'peer-analytics':peerAnalyticsPage,'risk-position':riskPositionPage,'collaboration':collaborationPage,'configured-alerts':configuredAlertsPage};
  main.innerHTML = specialized[page.id] ? specialized[page.id]() : topicPage(page);
  crumb.textContent = page.id==='home' ? '文件首頁' : `${page.group} / ${page.zh}`;
  renderNav(search.value);
  window.scrollTo(0,0);
  sidebar.classList.remove('open');
  menuBtn.setAttribute('aria-expanded','false');
}
search.addEventListener('input',() => renderNav(search.value));
window.addEventListener('hashchange',render);
main.addEventListener('click',event => {
  const target = event.target.closest('[data-page]');
  if(target) location.hash = target.dataset.page;
});
menuBtn.addEventListener('click',() => {
  const open = sidebar.classList.toggle('open');
  menuBtn.setAttribute('aria-expanded',String(open));
});
render();
